// 自動產生檔案，請勿手動編輯 —— 執行 build_book_text_data.py 重新產生
// 來源：bible_data/bible_text/DAN.json（A1下載產出）

const DAN_DATA = {"book": "DAN", "book_zh": "但以理書", "chapters": {"1": {"verses": {"1": {"en": "In the third year of the reign of Jehoiakim king of Judah, Nebuchadnezzar king of Babylon came to Jerusalem and besieged it.", "zh": "猶大王約雅敬在位第三年，巴比倫王尼布甲尼撒來到耶路撒冷，將城圍困。", "ja": "ユダの王エホヤキムの治世の第三年にバビロンの王ネブカデネザルはエルサレムにきて、これを攻め囲んだ。"}, "2": {"en": "The Lord gave Jehoiakim king of Judah into his hand, with some of the vessels of the house of God; and he carried them into the land of Shinar to the house of his god. He brought the vessels into the treasure house of his god.", "zh": "主將猶大王約雅敬，並上帝殿中器皿的幾分交付他手。他就把這器皿帶到示拿地，收入他神的廟裏，放在他神的庫中。", "ja": "主はユダの王エホヤキムと、神の宮の器具の一部とを、彼の手にわたされたので、彼はこれをシナルの地の自分の神の宮に携えゆき、その器具を自分の神の蔵に納めた。"}, "3": {"en": "The king spoke to Ashpenaz, the master of his eunuchs, that he should bring in some of the children of Israel, even of the royal offspring and of the nobles:", "zh": "王吩咐太監長亞施毗拿，從以色列人的宗室和貴冑中帶進幾個人來，", "ja": "時に王は宦官の長アシペナズに、イスラエルの人々の中から、王の血統の者と、貴族たる者数人とを、連れて来るように命じた。"}, "4": {"en": "youths in whom was no defect, but well-favored, skillful in all wisdom, endowed with knowledge, understanding science, and who had the ability to stand in the king’s palace; and that he should teach them the learning and the language of the Chaldeans.", "zh": "就是年少沒有殘疾、相貌俊美、通達各樣學問、知識聰明俱備、足能侍立在王宮裏的，要教他們迦勒底的文字言語。", "ja": "すなわち身に傷がなく、容姿が美しく、すべての知恵にさとく、知識があって、思慮深く、王の宮に仕えるに足る若者を連れてこさせ、これにカルデヤびとの文学と言語とを学ばせようとした。"}, "5": {"en": "The king appointed for them a daily portion of the king’s delicacies and of the wine which he drank, and that they should be nourished three years, that at its end they should stand before the king.", "zh": "王派定將自己所用的膳和所飲的酒，每日賜他們一分，養他們三年。滿了三年，好叫他們在王面前侍立。", "ja": "そして王は王の食べる食物と、王の飲む酒の中から、日々の分を彼らに与えて、三年のあいだ彼らを養い育て、その後、彼らをして王の前に、はべらせようとした。"}, "6": {"en": "Now among these of the children of Judah were Daniel, Hananiah, Mishael, and Azariah.", "zh": "他們中間有猶大族的人：但以理、哈拿尼雅、米沙利、亞撒利雅。", "ja": "彼らのうちに、ユダの部族のダニエル、ハナニヤ、ミシャエル、アザリヤがあった。"}, "7": {"en": "The prince of the eunuchs gave names to them: to Daniel he gave the name Belteshazzar; to Hananiah, Shadrach; to Mishael, Meshach; and to Azariah, Abednego.", "zh": "太監長給他們起名：稱但以理為伯提沙撒，稱哈拿尼雅為沙得拉，稱米沙利為米煞，稱亞撒利雅為亞伯尼歌。", "ja": "宦官の長は彼らに名を与えて、ダニエルをベルテシャザルと名づけ、ハナニヤをシャデラクと名づけ、ミシャエルをメシャクと名づけ、アザリヤをアベデネゴと名づけた。"}, "8": {"en": "But Daniel purposed in his heart that he would not defile himself with the king’s delicacies, nor with the wine which he drank. Therefore he requested of the prince of the eunuchs that he might not defile himself.", "zh": "但以理卻立志不以王的膳和王所飲的酒玷污自己，所以求太監長容他不玷污自己。", "ja": "ダニエルは王の食物と、王の飲む酒とをもって、自分を汚すまいと、心に思い定めたので、自分を汚させることのないように、宦官の長に求めた。"}, "9": {"en": "Now God made Daniel find kindness and compassion in the sight of the prince of the eunuchs.", "zh": "上帝使但以理在太監長眼前蒙恩惠，受憐憫。", "ja": "神はダニエルをして、宦官の長の前に、恵みとあわれみとを得させられたので、"}, "10": {"en": "The prince of the eunuchs said to Daniel, “I fear my lord the king, who has appointed your food and your drink. For why should he see your faces worse looking than the youths who are of your own age? Then you would endanger my head with the king.”", "zh": "太監長對但以理說：「我懼怕我主我王，他已經派定你們的飲食，倘若他見你們的面貌比你們同歲的少年人肌瘦，怎麼好呢？這樣，你們就使我的頭在王那裏難保。」", "ja": "宦官の長はダニエルに言った、「わが主なる王は、あなたがたの食べ物と、飲み物とを定められたので、わたしはあなたがたの健康の状態が、同年輩の若者たちよりも悪いと、王が見られることを恐れるのです。そうすればあなたがたのために、わたしのこうべが、王の前に危くなるでしょう」。"}, "11": {"en": "Then Daniel said to the steward whom the prince of the eunuchs had appointed over Daniel, Hananiah, Mishael, and Azariah:", "zh": "但以理對太監長所派管理但以理、哈拿尼雅、米沙利、亞撒利雅的委辦說：", "ja": "そこでダニエルは宦官の長がダニエル、ハナニヤ、ミシャエルおよびアザリヤの上に立てた家令に言った、"}, "12": {"en": "“Test your servants, I beg you, ten days; and let them give us vegetables to eat and water to drink.", "zh": "「求你試試僕人們十天，給我們素菜吃，白水喝，", "ja": "「どうぞ、しもべらを十日の間ためしてください。わたしたちにただ野菜を与えて食べさせ、水を飲ませ、"}, "13": {"en": "Then let our faces be examined before you, and the face of the youths who eat of the king’s delicacies; and as you see, deal with your servants.”", "zh": "然後看看我們的面貌和用王膳那少年人的面貌，就照你所看的待僕人吧！」", "ja": "そしてわたしたちの顔色と、王の食物を食べる若者の顔色とをくらべて見て、あなたの見るところにしたがって、しもべらを扱ってください」。"}, "14": {"en": "So he listened to them in this matter, and tested them for ten days.", "zh": "委辦便允准他們這件事，試看他們十天。", "ja": "家令はこの事について彼らの言うところを聞きいれ、十日の間、彼らをためした。"}, "15": {"en": "At the end of ten days, their faces appeared fairer and they were fatter in flesh than all the youths who ate of the king’s delicacies.", "zh": "過了十天，見他們的面貌比用王膳的一切少年人更加俊美肥胖。", "ja": "十日の終りになってみると、彼らの顔色は王の食物を食べたすべての若者よりも美しく、また肉も肥え太っていた。"}, "16": {"en": "So the steward took away their delicacies and the wine that they were given to drink, and gave them vegetables.", "zh": "於是委辦撤去派他們用的膳，飲的酒，給他們素菜吃。", "ja": "それで家令は彼らの食物と、彼らの飲むべき酒とを除いて、彼らに野菜を与えた。"}, "17": {"en": "Now as for these four youths, God gave them knowledge and skill in all learning and wisdom; and Daniel had understanding in all visions and dreams.", "zh": "這四個少年人，上帝在各樣文字學問上賜給他們聰明知識；但以理又明白各樣的異象和夢兆。", "ja": "この四人の者には、神は知識を与え、すべての文学と知恵にさとい者とされた。ダニエルはまたすべての幻と夢とを理解した。"}, "18": {"en": "At the end of the days which the king had appointed for bringing them in, the prince of the eunuchs brought them in before Nebuchadnezzar.", "zh": "尼布甲尼撒王預定帶進少年人來的日期滿了，太監長就把他們帶到王面前。", "ja": "さて、王が命じたところの若者を召し入れるまでの日数が過ぎたので、宦官の町は彼らをネブカデネザルの前に連れていった。"}, "19": {"en": "The king talked with them; and among them all was found no one like Daniel, Hananiah, Mishael, and Azariah. Therefore they stood before the king.", "zh": "王與他們談論，見少年人中無一人能比但以理、哈拿尼雅、米沙利、亞撒利雅，所以留他們在王面前侍立。", "ja": "王が彼らと語ってみると、彼らすべての中にはダニエル、ハナニヤ、ミシャエル、アザリヤにならぶ者がなかったので、彼らは王の前にはべることとなった。"}, "20": {"en": "In every matter of wisdom and understanding concerning which the king inquired of them, he found them ten times better than all the magicians and enchanters who were in all his realm.", "zh": "王考問他們一切事，就見他們的智慧聰明比通國的術士和用法術的勝過十倍。", "ja": "王が彼らにさまざまの事を尋ねてみると、彼らは知恵と理解において、全国の博士、法術士にまさること十倍であった。"}, "21": {"en": "Daniel continued even to the first year of King Cyrus.", "zh": "到塞魯士王元年，但以理還在。", "ja": "ダニエルはクロス王の元年まで仕えていた。"}}}, "2": {"verses": {"1": {"en": "In the second year of the reign of Nebuchadnezzar, Nebuchadnezzar dreamed dreams; and his spirit was troubled, and his sleep went from him.", "zh": "尼布甲尼撒在位第二年，他做了夢，心裏煩亂，不能睡覺。", "ja": "ネブカデネザルの治世の第二年に、ネブカデネザルは夢を見、そのために心に思い悩んで眠ることができなかった。"}, "2": {"en": "Then the king commanded that the magicians, the enchanters, the sorcerers, and the Chaldeans be called to tell the king his dreams. So they came in and stood before the king.", "zh": "王吩咐人將術士、用法術的、行邪術的，和迦勒底人召來，要他們將王的夢告訴王，他們就來站在王前。", "ja": "そこで王は命じて王のためにその夢を解かせようと、博士、法術士、魔術士、カルデヤびとを召させたので、彼らはきて王の前に立った。"}, "3": {"en": "The king said to them, “I have dreamed a dream, and my spirit is troubled to know the dream.”", "zh": "王對他們說：「我做了一夢，心裏煩亂，要知道這是甚麼夢。」", "ja": "王は彼らにむかって、「わたしは夢を見たが、その夢を知ろうと心に思い悩んでいる」と言ったので、"}, "4": {"en": "Then the Chaldeans spoke to the king in the Syrian language, “O king, live forever! Tell your servants the dream, and we will show the interpretation.”", "zh": "迦勒底人用亞蘭的言語對王說：「願王萬歲！請將那夢告訴僕人，僕人就可以講解。」", "ja": "カルデヤびとらはアラム語で王に言った、「王よ、とこしえに生きながらえられますように。どうぞしもべらにその夢をお話しください。わたしたちはその解き明かしを申しあげましょう」。"}, "5": {"en": "The king answered the Chaldeans, “The thing has gone from me. If you don’t make known to me the dream and its interpretation, you will be cut in pieces, and your houses will be made a dunghill.", "zh": "王回答迦勒底人說：「夢我已經忘了，你們若不將夢和夢的講解告訴我，就必被凌遲，你們的房屋必成為糞堆；", "ja": "王は答えてカルデヤびとに言った、「わたしの言うことは必ず行う。あなたがたがもしその夢と、その解き明かしを、わたしに示さないならば、あなたがたの身は切り裂かれ、あなたがたの家は滅ぼされる。"}, "6": {"en": "But if you show the dream and its interpretation, you will receive from me gifts, rewards, and great honor. Therefore show me the dream and its interpretation.”", "zh": "你們若將夢和夢的講解告訴我，就必從我這裏得贈品和賞賜，並大尊榮。現在你們要將夢和夢的講解告訴我。」", "ja": "しかし、その夢とその解き明かしとを示すならば、贈り物と報酬と大いなる栄誉とを、わたしから受けるだろう。それゆえその夢とその解き明かしとを、わたしに示しなさい」。"}, "7": {"en": "They answered the second time and said, “Let the king tell his servants the dream, and we will show the interpretation.”", "zh": "他們第二次對王說：「請王將夢告訴僕人，僕人就可以講解。」", "ja": "彼らは再び答えて言った、「王よ、しもべらにその夢をお話しください。そうすればわたしたちはその解き明かしを示しましょう」。"}, "8": {"en": "The king answered, “I know of a certainty that you are trying to gain time, because you see the thing has gone from me.", "zh": "王回答說：「我准知道你們是故意遲延，因為你們知道那夢我已經忘了。", "ja": "王は答えて言った、「あなたがたはわたしが言ったことは、必ず行うことを承知しているので、時を延ばそうとしているのを、わたしは確かに知っている。"}, "9": {"en": "But if you don’t make known to me the dream, there is but one law for you; for you have prepared lying and corrupt words to speak before me, until the situation changes. Therefore tell me the dream, and I will know that you can show me its interpretation.”", "zh": "你們若不將夢告訴我，只有一法待你們；因為你們預備了謊言亂語向我說，要等候時勢改變。現在你們要將夢告訴我，因我知道你們能將夢的講解告訴我。」", "ja": "もしその夢をわたしに示さないならば、あなたがたの受ける刑罰はただ一つあるのみだ。あなたがたは一致して、偽りと、欺きの言葉をわたしの前に述べて、時の変るのを待とうとしているのだ。まずその夢をわたしに示しなさい。そうすれば、わたしはあなたがたがその解き明かしをも、示しうることを知るだろう」。"}, "10": {"en": "The Chaldeans answered the king and said, “There is not a man on the earth who can show the king’s matter, because no king, lord, or ruler has asked such a thing of any magician, enchanter, or Chaldean.", "zh": "迦勒底人在王面前回答說：「世上沒有人能將王所問的事說出來；因為沒有君王、大臣、掌權的向術士，或用法術的，或迦勒底人問過這樣的事。", "ja": "カルデヤびとらは王の前に答えて言った、「世の中には王のその要求に応じうる者はひとりもありません。どんな大いなる力ある王でも、このような事を、博士、法術士、カルデヤびとに尋ねた者はありませんでした。"}, "11": {"en": "It is a rare thing that the king requires, and there is no other who can show it before the king except the gods, whose dwelling is not with flesh.”", "zh": "王所問的事甚難。除了不與世人同居的神明，沒有人在王面前能說出來。」", "ja": "王の尋ねられる事はむずかしい事であって、肉なる者と共におられない神々を除いては、王の前にこれを示しうる者はないでしょう」。"}, "12": {"en": "Because of this, the king was angry and very furious, and commanded that all the wise men of Babylon be destroyed.", "zh": "因此，王氣忿忿地大發烈怒，吩咐滅絕巴比倫所有的哲士。", "ja": "これによって王は怒り、かつ大いに憤り、バビロンの知者をすべて滅ぼせと命じた。"}, "13": {"en": "So the decree went out, and the wise men were to be slain. They sought Daniel and his companions to be slain.", "zh": "於是命令發出，哲士將要見殺，人就尋找但以理和他的同伴，要殺他們。", "ja": "この命令が発せられたので、知者らは殺されることになった。またダニエルとその同僚をも殺そうと求めた。"}, "14": {"en": "Then Daniel returned answer with counsel and prudence to Arioch the captain of the king’s guard, who had gone out to kill the wise men of Babylon.", "zh": "王的護衛長亞略出來，要殺巴比倫的哲士，但以理就用婉言回答他，", "ja": "そして王の侍衛の長アリオクが、バビロンの知者らを殺そうと出てきたので、ダニエルは思慮と知恵とをもってこれに応答した。"}, "15": {"en": "He answered Arioch the king’s captain, “Why is the decree so urgent from the king?” Then Arioch made the thing known to Daniel.", "zh": "向王的護衛長亞略說：「王的命令為何這樣緊急呢？」亞略就將情節告訴但以理。", "ja": "すなわち王の高官アリオクに「どうして王はそんなにきびしい命令を出されたのですか」と言った。アリオクがその事をダニエルに告げ知らせると、"}, "16": {"en": "Daniel went in, and desired of the king that he would appoint him a time, and he would show the king the interpretation.", "zh": "但以理遂進去求王寬限，就可以將夢的講解告訴王。", "ja": "ダニエルは王のところへはいっていって、その解き明かしを示すために、しばらくの時を与えられるよう王に願った。"}, "17": {"en": "Then Daniel went to his house and made the thing known to Hananiah, Mishael, and Azariah, his companions:", "zh": "但以理回到他的居所，將這事告訴他的同伴哈拿尼雅、米沙利、亞撒利雅，", "ja": "それからダニエルは家に帰り、同僚のハナニヤ、ミシャエルおよびアザリヤにこの事を告げ知らせ、"}, "18": {"en": "that they would desire mercies of the God of heaven concerning this secret, that Daniel and his companions would not perish with the rest of the wise men of Babylon.", "zh": "要他們祈求天上的上帝施憐憫，將這奧祕的事指明，免得但以理和他的同伴與巴比倫其餘的哲士一同滅亡。", "ja": "共にこの秘密について天の神のあわれみを請い、ダニエルとその同僚とが、他のバビロンの知者と共に滅ぼされることのないように求めた。"}, "19": {"en": "Then the secret was revealed to Daniel in a vision of the night. Then Daniel blessed the God of heaven.", "zh": "這奧祕的事就在夜間異象中給但以理顯明，但以理便稱頌天上的上帝。", "ja": "ついに夜の幻のうちにこの秘密がダニエルに示されたので、ダニエルは天の神をほめたたえた。"}, "20": {"en": "Daniel answered, “Blessed be the name of God forever and ever; for wisdom and might are his.", "zh": "但以理說：「上帝的名是應當稱頌的！從亙古直到永遠，因為智慧能力都屬乎他。", "ja": "ダニエルは言った、「神のみ名は永遠より永遠に至るまでほむべきかな、知恵と権能とは神のものである。"}, "21": {"en": "He changes the times and the seasons. He removes kings and sets up kings. He gives wisdom to the wise, and knowledge to those who have understanding.", "zh": "他改變時候、日期，廢王，立王，將智慧賜與智慧人，將知識賜與聰明人。", "ja": "神は時と季節とを変じ、王を廃し、王を立て、知者に知恵を与え、賢者に知識を授けられる。"}, "22": {"en": "He reveals the deep and secret things. He knows what is in the darkness, and the light dwells with him.", "zh": "他顯明深奧隱秘的事，知道暗中所有的，光明也與他同居。", "ja": "神は深妙、秘密の事をあらわし、暗黒にあるものを知り、光をご自身のうちに宿す。"}, "23": {"en": "I thank you and praise you, O God of my fathers, who have given me wisdom and might, and have now made known to me what we desired of you; for you have made known to us the king’s matter.”", "zh": "我列祖的上帝啊，我感謝你，讚美你；因你將智慧才能賜給我，允准我們所求的，把王的事給我們指明。」", "ja": "わが先祖たちの神よ、あなたはわたしに知恵と力とを賜い、今われわれがあなたに請い求めたところのものをわたしに示し、王の求めたことをわれわれに示されたので、わたしはあなたに感謝し、あなたをさんびします」。"}, "24": {"en": "Therefore Daniel went in to Arioch, whom the king had appointed to destroy the wise men of Babylon. He went and said this to him: “Don’t destroy the wise men of Babylon. Bring me in before the king, and I will show to the king the interpretation.”", "zh": "於是，但以理進去見亞略，就是王所派滅絕巴比倫哲士的，對他說：「不要滅絕巴比倫的哲士，求你領我到王面前，我要將夢的講解告訴王。」", "ja": "そこでダニエルは、王がバビロンの知者たちを滅ぼすことを命じておいたアリオクのもとへ行って、彼にこう言った、「バビロンの知者たちを滅ぼしてはなりません。わたしを王の前に連れて行ってください。わたしはその解き明かしを王に示します」。"}, "25": {"en": "Then Arioch brought in Daniel before the king in haste, and said this to him: “I have found a man of the children of the captivity of Judah who will make known to the king the interpretation.”", "zh": "亞略就急忙將但以理領到王面前，對王說：「我在被擄的猶大人中遇見一人，他能將夢的講解告訴王。」", "ja": "アリオクは急いでダニエルを王の前に連れて行き、王にこう言った、「ユダから捕え移した者の中に、その解き明かしを王にお知らせすることのできる、ひとりの人を見つけました」。"}, "26": {"en": "The king answered Daniel, whose name was Belteshazzar, “Are you able to make known to me the dream which I have seen, and its interpretation?”", "zh": "王問稱為伯提沙撒的但以理說：「你能將我所做的夢和夢的講解告訴我嗎？」", "ja": "王は答えて、ベルテシャザルという名のダニエルに言った、「あなたはわたしが見た夢と、その解き明かしとをわたしに知らせることができるのか」。"}, "27": {"en": "Daniel answered before the king, and said, “The secret which the king has demanded can’t be shown to the king by wise men, enchanters, magicians, or soothsayers;", "zh": "但以理在王面前回答說：「王所問的那奧祕事，哲士、用法術的、術士、觀兆的都不能告訴王，", "ja": "ダニエルは王に答えて言った、「王が求められる秘密は、知者、法術士、博士、占い師など、これを王に示すことはできません。"}, "28": {"en": "but there is a God in heaven who reveals secrets, and he has made known to King Nebuchadnezzar what will be in the latter days. Your dream and the visions of your head on your bed are these:", "zh": "只有一位在天上的上帝能顯明奧祕的事。他已將日後必有的事指示尼布甲尼撒王。你的夢和你在床上腦中的異象是這樣：", "ja": "しかし秘密をあらわすひとりの神が天におられます。彼は後の日に起るべき事を、ネブカデネザル王に知らされたのです。あなたの夢と、あなたが床にあって見た脳中の幻はこれです。"}, "29": {"en": "“As for you, O king, your thoughts came on your bed, what should happen hereafter; and he who reveals secrets has made known to you what will happen.", "zh": "王啊，你在床上想到後來的事，那顯明奧祕事的主把將來必有的事指示你。", "ja": "王よ、あなたが床におられたとき、この後どんな事があろうかと、思いまわされたが、秘密をあらわされるかたが、将来どんな事が起るかを、あなたに知らされたのです。"}, "30": {"en": "But as for me, this secret is not revealed to me for any wisdom that I have more than any living, but to the intent that the interpretation may be made known to the king, and that you may know the thoughts of your heart.", "zh": "至於那奧祕的事顯明給我，並非因我的智慧勝過一切活人，乃為使王知道夢的講解和心裏的思念。", "ja": "この秘密をわたしにあらわされたのは、すべての生ける者にまさって、わたしに知恵があるためではなく、ただその解き明かしを、王にお知らせすることによって、あなたが心に思われたことを、お知りになるためです。"}, "31": {"en": "“You, O king, saw, and behold, a great image. This image, which was mighty, and whose brightness was excellent, stood before you; and its appearance was terrifying.", "zh": "「王啊，你夢見一個大像，這像甚高，極其光耀，站在你面前，形狀甚是可怕。", "ja": "王よ、あなたは一つの大いなる像が、あなたの前に立っているのを見られました。その像は大きく、非常に光り輝いて、恐ろしい外観をもっていました。"}, "32": {"en": "As for this image, its head was of fine gold, its chest and its arms of silver, its belly and its thighs of bronze,", "zh": "這像的頭是精金的，胸膛和膀臂是銀的，肚腹和腰是銅的，", "ja": "その像の頭は純金、胸と両腕とは銀、腹と、ももとは青銅、"}, "33": {"en": "its legs of iron, its feet part of iron and part of clay.", "zh": "腿是鐵的，腳是半鐵半泥的。", "ja": "すねは鉄、足の一部は鉄、一部は粘土です。"}, "34": {"en": "You saw until a stone was cut out without hands, which struck the image on its feet that were of iron and clay, and broke them in pieces.", "zh": "你觀看，見有一塊非人手鑿出來的石頭打在這像半鐵半泥的腳上，把腳砸碎；", "ja": "あなたが見ておられたとき、一つの石が人手によらずに切り出されて、その像の鉄と粘土との足を撃ち、これを砕きました。"}, "35": {"en": "Then the iron, the clay, the bronze, the silver, and the gold were broken in pieces together, and became like the chaff of the summer threshing floors. The wind carried them away, so that no place was found for them. The stone that struck the image became a great mountain and filled the whole earth.", "zh": "於是金、銀、銅、鐵、泥都一同砸得粉碎，成如夏天禾場上的糠詷，被風吹散，無處可尋。打碎這像的石頭變成一座大山，充滿天下。", "ja": "こうして鉄と、粘土と、青銅と、銀と、金とはみな共に砕けて、夏の打ち場のもみがらのようになり、風に吹き払われて、あとかたもなくなりました。ところがその像を撃った石は、大きな山となって全地に満ちました。"}, "36": {"en": "“This is the dream; and we will tell its interpretation before the king.", "zh": "「這就是那夢；我們在王面前要講解那夢。", "ja": "これがその夢です。今わたしたちはその解き明かしを、王の前に申しあげましょう。"}, "37": {"en": "You, O king, are king of kings, to whom the God of heaven has given the kingdom, the power, the strength, and the glory.", "zh": "王啊，你是諸王之王。天上的上帝已將國度、權柄、能力、尊榮都賜給你。", "ja": "王よ、あなたは諸王の王であって、天の神はあなたに国と力と勢いと栄えとを賜い、"}, "38": {"en": "Wherever the children of men dwell, he has given the animals of the field and the birds of the sky into your hand, and has made you rule over them all. You are the head of gold.", "zh": "凡世人所住之地的走獸，並天空的飛鳥，他都交付你手，使你掌管這一切。你就是那金頭。", "ja": "また人の子ら、野の獣、空の鳥はどこにいるものでも、皆これをあなたの手に与えて、ことごとく治めさせられました。あなたはあの金の頭です。"}, "39": {"en": "“After you, another kingdom will arise that is inferior to you; and another third kingdom of bronze, which will rule over all the earth.", "zh": "在你以後必另興一國，不及於你；又有第三國，就是銅的，必掌管天下。", "ja": "あなたの後にあなたに劣る一つの国が起ります。また第三に青銅の国が起って、全世界を治めるようになります。"}, "40": {"en": "The fourth kingdom will be strong as iron, because iron breaks in pieces and subdues all things; and as iron that crushes all these, it will break in pieces and crush.", "zh": "第四國，必堅壯如鐵，鐵能打碎剋制百物，又能壓碎一切，那國也必打碎壓制列國。", "ja": "第四の国は鉄のように強いでしょう。鉄はよくすべての物をこわし砕くからです。鉄がこれらをことごとく打ち砕くように、その国はこわし砕くでしょう。"}, "41": {"en": "Whereas you saw the feet and toes, part of potters’ clay and part of iron, it will be a divided kingdom; but there will be in it of the strength of the iron, because you saw the iron mixed with miry clay.", "zh": "你既見像的腳和腳指頭，一半是窯匠的泥，一半是鐵，那國將來也必分開。你既見鐵與泥攙雜，那國也必有鐵的力量。", "ja": "あなたはその足と足の指を見られましたが、その一部は陶器師の粘土、一部は鉄であったので、それは分裂した国をさします。しかしあなたが鉄と粘土との混じったのを見られたように、その国には鉄の強さがあるでしょう。"}, "42": {"en": "As the toes of the feet were part of iron, and part of clay, so the kingdom will be partly strong and partly brittle.", "zh": "那腳指頭，既是半鐵半泥，那國也必半強半弱。", "ja": "その足の指の一部は鉄、一部は粘土であったように、その国は一部は強く、一部はもろいでしょう。"}, "43": {"en": "Whereas you saw the iron mixed with miry clay, they will mingle themselves with the seed of men; but they won’t cling to one another, even as iron does not mix with clay.", "zh": "你既見鐵與泥攙雜，那國民也必與各種人攙雜，卻不能彼此相合，正如鐵與泥不能相合一樣。", "ja": "あなたが鉄と粘土との混じったのを見られたように、それらは婚姻によって、互に混ざるでしょう。しかし鉄と粘土とは相混じらないように、かれとこれと相合することはありません。"}, "44": {"en": "“In the days of those kings the God of heaven will set up a kingdom which will never be destroyed, nor will its sovereignty be left to another people; but it will break in pieces and consume all these kingdoms, and it will stand forever.", "zh": "當那列王在位的時候，天上的上帝必另立一國，永不敗壞，也不歸別國的人，卻要打碎滅絕那一切國，這國必存到永遠。", "ja": "それらの王たちの世に、天の神は一つの国を立てられます。これはいつまでも滅びることがなく、その主権は他の民にわたされず、かえってこれらのもろもろの国を打ち破って滅ぼすでしょう。そしてこの国は立って永遠に至るのです。"}, "45": {"en": "Because you saw that a stone was cut out of the mountain without hands, and that it broke in pieces the iron, the bronze, the clay, the silver, and the gold, the great God has made known to the king what will happen hereafter. The dream is certain, and its interpretation sure.”", "zh": "你既看見非人手鑿出來的一塊石頭從山而出，打碎金、銀、銅、鐵、泥，那就是至大的上帝把後來必有的事給王指明。這夢準是這樣，這講解也是確實的。」", "ja": "一つの石が人手によらずに山から切り出され、その石が鉄と、青銅と、粘土と、銀と、金とを打ち砕いたのを、あなたが見られたのはこの事です。大いなる神がこの後に起るべきことを、王に知らされたのです。その夢はまことであって、この解き明かしは確かです」。"}, "46": {"en": "Then King Nebuchadnezzar fell on his face, worshiped Daniel, and commanded that they should offer an offering and sweet odors to him.", "zh": "當時，尼布甲尼撒王俯伏在地，向但以理下拜，並且吩咐人給他奉上供物和香品。", "ja": "そこでネブカデネザル王はひれ伏して、ダニエルを拝し、供え物と薫香とを、彼にささげることを命じた。"}, "47": {"en": "The king answered to Daniel, and said, “Of a truth your God is the God of gods, and the Lord of kings, and a revealer of secrets, since you have been able to reveal this secret.”", "zh": "王對但以理說：「你既能顯明這奧祕的事，你們的上帝誠然是萬神之神、萬王之主，又是顯明奧祕事的。」", "ja": "そして王はダニエルに答えて言った、「あなたがこの秘密をあらわすことができたのを見ると、まことに、あなたがたの神は神々の神、王たちの主であって、秘密をあらわされるかただ」。"}, "48": {"en": "Then the king made Daniel great and gave him many great gifts, and made him rule over the whole province of Babylon and to be chief governor over all the wise men of Babylon.", "zh": "於是王高抬但以理，賞賜他許多上等禮物，派他管理巴比倫全省，又立他為總理，掌管巴比倫的一切哲士。", "ja": "こうして王はダニエルに高い位を授け、多くの大いなる贈り物を与えて、彼をバビロン全州の総督とし、またバビロンの知者たちを統轄する者の長とした。"}, "49": {"en": "Daniel requested of the king, and he appointed Shadrach, Meshach, and Abednego over the affairs of the province of Babylon, but Daniel was in the king’s gate.", "zh": "但以理求王，王就派沙得拉、米煞、亞伯尼歌管理巴比倫省的事務，只是但以理常在朝中侍立。", "ja": "王はまたダニエルの願いによって、シャデラクとメシャクとアベデネゴを任命して、バビロン州の事務をつかさどらせた。ただしダニエルは王の宮にとどまっていた。"}}}, "3": {"verses": {"1": {"en": "Nebuchadnezzar the king made an image of gold, whose height was sixty cubits and its width six cubits. He set it up in the plain of Dura, in the province of Babylon.", "zh": "尼布甲尼撒王造了一個金像，高六十肘，寬六肘，立在巴比倫省杜拉平原。", "ja": "ネブカデネザル王は一つの金の像を造った。その高さは六十キュビト、その幅は六キュビトで、彼はこれをバビロン州のドラの平野に立てた。"}, "2": {"en": "Then Nebuchadnezzar the king sent to gather together the local governors, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces, to come to the dedication of the image which Nebuchadnezzar the king had set up.", "zh": "尼布甲尼撒王差人將總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都召了來，為尼布甲尼撒王所立的像行開光之禮。", "ja": "そしてネブカデネザル王は、総督、長官、知事、参議、庫官、法官、高僧および諸州の官吏たちを召し集め、ネブカデネザル王の立てたこの像の落成式に臨ませようとした。"}, "3": {"en": "Then the local governors, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces were gathered together to the dedication of the image that Nebuchadnezzar the king had set up; and they stood before the image that Nebuchadnezzar had set up.", "zh": "於是總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都聚集了來，要為尼布甲尼撒王所立的像行開光之禮，就站在尼布甲尼撒所立的像前。", "ja": "そこで、総督、長官、知事、参議、庫官、法官、高僧および諸州の官吏たちは、ネブカデネザル王の立てた像の落成式に臨み、そのネブカデネザルの立てた像の前に立った。"}, "4": {"en": "Then the herald cried aloud, “To you it is commanded, peoples, nations, and languages,", "zh": "那時傳令的大聲呼叫說：「各方、各國、各族的人哪，有令傳與你們：", "ja": "時に伝令者は大声に呼ばわって言った、「諸民、諸族、諸国語の者よ、あなたがたにこう命じられる。"}, "5": {"en": "that whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, you fall down and worship the golden image that Nebuchadnezzar the king has set up.", "zh": "你們一聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，就當俯伏敬拜尼布甲尼撒王所立的金像。", "ja": "角笛、横笛、琴、三角琴、立琴、風笛などの、もろもろの楽器の音を聞く時は、ひれ伏してネブカデネザル王の立てた金の像を拝まなければならない。"}, "6": {"en": "Whoever doesn’t fall down and worship shall be cast into the middle of a burning fiery furnace the same hour.”", "zh": "凡不俯伏敬拜的，必立時扔在烈火的窯中。」", "ja": "だれでもひれ伏して拝まない者は、ただちに火の燃える炉の中に投げ込まれる」と。"}, "7": {"en": "Therefore at that time, when all the peoples heard the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, all the peoples, the nations, and the languages fell down and worshiped the golden image that Nebuchadnezzar the king had set up.", "zh": "因此各方、各國、各族的人民一聽見角、笛、琵琶、琴、瑟，和各樣樂器的聲音，就都俯伏敬拜尼布甲尼撒王所立的金像。", "ja": "そこで民らはみな、角笛、横笛、琴、三角琴、立琴、風笛などの、もろもろの楽器の音を聞くや、諸民、諸族、諸国語の者たちはみな、ひれ伏して、ネブカデネザル王の立てた金の像を拝んだ。"}, "8": {"en": "Therefore at that time certain Chaldeans came near and brought accusation against the Jews.", "zh": "那時，有幾個迦勒底人進前來控告猶大人。", "ja": "その時、あるカルデヤびとらが進みきて、ユダヤ人をあしざまに訴えた。"}, "9": {"en": "They answered Nebuchadnezzar the king, “O king, live for ever!", "zh": "他們對尼布甲尼撒王說：「願王萬歲！", "ja": "すなわち彼らはネブカデネザル王に言った、「王よ、とこしえに生きながらえられますように。"}, "10": {"en": "You, O king, have made a decree that every man who hears the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music shall fall down and worship the golden image;", "zh": "王啊，你曾降旨說，凡聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器聲音的都當俯伏敬拜金像。", "ja": "王よ、あなたは命令を出して仰せられました。すべて、角笛、横笛、琴、三角琴、立琴、風笛などの、もろもろの楽器の音を聞く者は皆、ひれ伏して金の像を拝まなければならない。"}, "11": {"en": "and whoever doesn’t fall down and worship shall be cast into the middle of a burning fiery furnace.", "zh": "凡不俯伏敬拜的，必扔在烈火的窯中。", "ja": "また、だれでもひれ伏して拝まない者はみな、火の燃える炉の中に投げ込まれると。"}, "12": {"en": "There are certain Jews whom you have appointed over the affairs of the province of Babylon: Shadrach, Meshach, and Abednego. These men, O king, have not respected you. They don’t serve your gods, and don’t worship the golden image which you have set up.”", "zh": "現在有幾個猶大人，就是王所派管理巴比倫省事務的沙得拉、米煞、亞伯尼歌；王啊，這些人不理你，不事奉你的神，也不敬拜你所立的金像。」", "ja": "ここにあなたが任命して、バビロン州の事務をつかさどらせられているユダヤ人シャデラク、メシャクおよびアベデネゴがおります。王よ、この人々はあなたを尊ばず、あなたの神々にも仕えず、あなたの立てられた金の像をも拝もうとしません」。"}, "13": {"en": "Then Nebuchadnezzar in rage and fury commanded that Shadrach, Meshach, and Abednego be brought. Then these men were brought before the king.", "zh": "當時，尼布甲尼撒沖沖大怒，吩咐人把沙得拉、米煞、亞伯尼歌帶過來，他們就把那些人帶到王面前。", "ja": "そこでネブカデネザルは怒りかつ憤って、シャデラク、メシャクおよびアベデネゴを連れてこいと命じたので、この人々を王の前に連れてきた。"}, "14": {"en": "Nebuchadnezzar answered them, “Is it true, Shadrach, Meshach, and Abednego, that you don’t serve my gods and you don’t worship the golden image which I have set up?", "zh": "尼布甲尼撒問他們說：「沙得拉、米煞、亞伯尼歌，你們不事奉我的神，也不敬拜我所立的金像，是故意的嗎？", "ja": "ネブカデネザルは彼らに言った、「シャデラク、メシャク、アベデネゴよ、あなたがたがわが神々に仕えず、またわたしの立てた金の像を拝まないとは、ほんとうなのか。"}, "15": {"en": "Now if you are ready whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music to fall down and worship the image which I have made, good; but if you don’t worship, you shall be cast the same hour into the middle of a burning fiery furnace. Who is that god who will deliver you out of my hands?”", "zh": "你們再聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，若俯伏敬拜我所造的像，卻還可以；若不敬拜，必立時扔在烈火的窯中，有何神能救你們脫離我手呢？」", "ja": "あなたがたがもし、角笛、横笛、琴、三角琴、立琴、風笛などの、もろもろの楽器の音を聞くときにひれ伏して、わたしが立てた像を、ただちに拝むならば、それでよろしい。しかし、拝むことをしないならば、ただちに火の燃える炉の中に投げ込まれる。いったい、どの神が、わたしの手からあなたがたを救うことができようか」。"}, "16": {"en": "Shadrach, Meshach, and Abednego answered the king, “Nebuchadnezzar, we have no need to answer you in this matter.", "zh": "沙得拉、米煞、亞伯尼歌對王說：「尼布甲尼撒啊，這件事我們不必回答你，", "ja": "シャデラク、メシャクおよびアベデネゴは王に答えて言った、「ネブカデネザルよ、この事について、お答えする必要はありません。"}, "17": {"en": "If it happens, our God whom we serve is able to deliver us from the burning fiery furnace; and he will deliver us out of your hand, O king.", "zh": "即便如此，我們所事奉的上帝能將我們從烈火的窯中救出來。王啊，他也必救我們脫離你的手；", "ja": "もしそんなことになれば、わたしたちの仕えている神は、その火の燃える炉から、わたしたちを救い出すことができます。また王よ、あなたの手から、わたしたちを救い出されます。"}, "18": {"en": "But if not, let it be known to you, O king, that we will not serve your gods or worship the golden image which you have set up.”", "zh": "即或不然，王啊，你當知道我們決不事奉你的神，也不敬拜你所立的金像。」", "ja": "たといそうでなくても、王よ、ご承知ください。わたしたちはあなたの神々に仕えず、またあなたの立てた金の像を拝みません」。"}, "19": {"en": "Then Nebuchadnezzar was full of fury, and the form of his appearance was changed against Shadrach, Meshach, and Abednego. He spoke, and commanded that they should heat the furnace seven times more than it was usually heated.", "zh": "當時，尼布甲尼撒怒氣填胸，向沙得拉、米煞、亞伯尼歌變了臉色，吩咐人把窯燒熱，比尋常更加七倍；", "ja": "そこでネブカデネザルは怒りに満ち、シャデラク、メシャクおよびアベデネゴにむかって、顔色を変え、炉を平常よりも七倍熱くせよと命じた。"}, "20": {"en": "He commanded certain mighty men who were in his army to bind Shadrach, Meshach, and Abednego, and to cast them into the burning fiery furnace.", "zh": "又吩咐他軍中的幾個壯士，將沙得拉、米煞、亞伯尼歌捆起來，扔在烈火的窯中。", "ja": "またその軍勢の中の力の強い人々を呼んで、シャデラク、メシャクおよびアベデネゴを縛って、彼らを火の燃える炉の中に投げ込めと命じた。"}, "21": {"en": "Then these men were bound in their pants, their tunics, and their mantles, and their other clothes, and were cast into the middle of the burning fiery furnace.", "zh": "這三人穿着褲子、內袍、外衣，和別的衣服，被捆起來扔在烈火的窯中。", "ja": "そこでこの人々は、外套、下着、帽子、その他の衣服のまま縛られて、火の燃える炉の中に投げ込まれた。"}, "22": {"en": "Therefore because the king’s commandment was urgent and the furnace exceedingly hot, the flame of the fire killed those men who took up Shadrach, Meshach, and Abednego.", "zh": "因為王命緊急，窯又甚熱，那抬沙得拉、米煞、亞伯尼歌的人都被火焰燒死。", "ja": "王の命令はきびしく、かつ炉は、はなはだしく熱していたので、シャデラク、メシャクおよびアベデネゴを引きつれていった人々は、その火炎に焼き殺された。"}, "23": {"en": "These three men, Shadrach, Meshach, and Abednego, fell down bound into the middle of the burning fiery furnace.", "zh": "沙得拉、米煞、亞伯尼歌這三個人都被捆着落在烈火的窯中。", "ja": "シャデラク、メシャク、アベデネゴの三人は縛られたままで、火の燃える炉の中に落ち込んだ。"}, "24": {"en": "Then Nebuchadnezzar the king was astonished and rose up in haste. He spoke and said to his counselors, “Didn’t we cast three men bound into the middle of the fire?” They answered the king, “True, O king.”", "zh": "那時，尼布甲尼撒王驚奇，急忙起來，對謀士說：「我們捆起來扔在火裏的不是三個人嗎？」他們回答王說：「王啊，是。」", "ja": "その時、ネブカデネザル王は驚いて急ぎ立ちあがり、大臣たちに言った、「われわれはあの三人を縛って、火の中に投げ入れたではないか」。彼らは王に答えて言った、「王よ、そのとおりです」。"}, "25": {"en": "He answered, “Look, I see four men loose, walking in the middle of the fire, and they are unharmed. The appearance of the fourth is like a son of the gods.”", "zh": "王說：「看哪，我見有四個人，並沒有捆綁，在火中遊行，也沒有受傷；那第四個的相貌好像神子。」", "ja": "王は答えて言った、「しかし、わたしの見るのに四人の者がなわめなしに、火の中を歩いているが、なんの害をも受けていない。その第四の者の様子は神の子のようだ」。"}, "26": {"en": "Then Nebuchadnezzar came near to the mouth of the burning fiery furnace. He spoke and said, “Shadrach, Meshach, and Abednego, you servants of the Most High God, come out, and come here!”", "zh": "於是，尼布甲尼撒就近烈火窯門，說：「至高上帝的僕人沙得拉、米煞、亞伯尼歌出來，上這裏來吧！」沙得拉、米煞、亞伯尼歌就從火中出來了。", "ja": "そこでネブカデネザルは、その火の燃える炉の入口に近寄って、「いと高き神のしもべシャデラク、メシャク、アベデネゴよ、出てきなさい」と言ったので、シャデラク、メシャク、アベデネゴはその火の中から出てきた。"}, "27": {"en": "Then Shadrach, Meshach, and Abednego came out of the middle of the fire.   The local governors, the deputies, and the governors, and the king’s counselors, being gathered together, saw these men, that the fire had no power on their bodies. The hair of their head wasn’t singed. Their pants weren’t changed. The smell of fire wasn’t even on them.", "zh": "那些總督、欽差、巡撫，和王的謀士一同聚集看這三個人，見火無力傷他們的身體，頭髮也沒有燒焦，衣裳也沒有變色，並沒有火燎的氣味。", "ja": "総督、長官、知事および王の大臣たちも集まってきて、この人々を見たが、火は彼らの身にはなんの力もなく、その頭の毛は焼けず、その外套はそこなわれず、火のにおいもこれに付かなかった。"}, "28": {"en": "Nebuchadnezzar spoke and said, “Blessed be the God of Shadrach, Meshach, and Abednego, who has sent his angel and delivered his servants who trusted in him, and have changed the king’s word, and have yielded their bodies, that they might not serve nor worship any god except their own God.", "zh": "尼布甲尼撒說：「沙得拉、米煞、亞伯尼歌的上帝是應當稱頌的！他差遣使者救護倚靠他的僕人，他們不遵王命，捨去己身，在他們上帝以外不肯事奉敬拜別神。", "ja": "ネブカデネザルは言った、「シャデラク、メシャク、アベデネゴの神はほむべきかな。神はその使者をつかわして、自分に寄り頼むしもべらを救った。また彼らは自分の神以外の神に仕え、拝むよりも、むしろ王の命令を無視し、自分の身をも捨てようとしたのだ。"}, "29": {"en": "Therefore I make a decree that every people, nation, and language which speak anything evil against the God of Shadrach, Meshach, and Abednego shall be cut in pieces, and their houses shall be made a dunghill, because there is no other god who is able to deliver like this.”", "zh": "現在我降旨，無論何方、何國、何族的人，謗讟沙得拉、米煞、亞伯尼歌之上帝的，必被凌遲，他的房屋必成糞堆，因為沒有別神能這樣施行拯救。」", "ja": "それでわたしはいま命令を下す。諸民、諸族、諸国語の者のうちだれでも、シャデラク、メシャク、アベデネゴの神をののしる者があるならば、その身は切り裂かれ、その家は滅ぼされなければならない。このように救を施すことのできる神は、ほかにないからだ」。"}, "30": {"en": "Then the king promoted Shadrach, Meshach, and Abednego in the province of Babylon.", "zh": "那時王在巴比倫省，高升了沙得拉、米煞、亞伯尼歌。", "ja": "こうして、王はシャデラク、メシャクおよびアベデネゴの位を進めて、バビロン州におらせた。"}}}, "4": {"verses": {"1": {"en": "Nebuchadnezzar the king, to all the peoples, nations, and languages, who dwell in all the earth: Peace be multiplied to you.", "zh": "尼布甲尼撒王曉諭住在全地各方、各國、各族的人說：「願你們大享平安！", "ja": "ネブカデネザル王は全世界に住む諸民、諸族、諸国語の者に告げる。どうか、あなたがたに平安が増すように。"}, "2": {"en": "It has seemed good to me to show the signs and wonders that the Most High God has worked toward me.", "zh": "我樂意將至高的上帝向我所行的神蹟奇事宣揚出來。", "ja": "いと高き神はわたしにしるしと奇跡とを行われた。わたしはこれを知らせたいと思う。"}, "3": {"en": "How great are his signs! How mighty are his wonders! His kingdom is an everlasting kingdom. His dominion is from generation to generation.", "zh": "他的神蹟何其大！ 他的奇事何其盛！ 他的國是永遠的； 他的權柄存到萬代！", "ja": "ああ、そのしるしの大いなること、ああ、その奇跡のすばらしいこと、その国は永遠の国、その主権は世々に及ぶ。"}, "4": {"en": "I, Nebuchadnezzar, was at rest in my house, and flourishing in my palace.", "zh": "「我－尼布甲尼撒安居在宮中，平順在殿內。", "ja": "われネブカデネザルはわが家に安らかにおり、わが宮にあって栄えていたが、"}, "5": {"en": "I saw a dream which made me afraid; and the thoughts on my bed and the visions of my head troubled me.", "zh": "我做了一夢，使我懼怕。我在床上的思念，並腦中的異象，使我驚惶。", "ja": "わたしは一つの夢を見て、そのために恐れた。すなわち床にあって、その事を思いめぐらし、わが脳中の幻のために心を悩ました。"}, "6": {"en": "Therefore I made a decree to bring in all the wise men of Babylon before me, that they might make known to me the interpretation of the dream.", "zh": "所以我降旨召巴比倫的一切哲士到我面前，叫他們把夢的講解告訴我。", "ja": "そこでわたしは命令を下し、バビロンの知者をことごとくわが前に召し寄せて、その夢の解き明かしを示させようとした。"}, "7": {"en": "Then the magicians, the enchanters, the Chaldeans, and the soothsayers came in; and I told them the dream, but they didn’t make known to me its interpretation.", "zh": "於是那些術士、用法術的、迦勒底人、觀兆的都進來，我將那夢告訴了他們，他們卻不能把夢的講解告訴我。", "ja": "すると、博士、法術士、カルデヤびと、占い師たちがきたので、わたしはその夢を彼らに語ったが、彼らはその解き明かしを示すことができなかった。"}, "8": {"en": "But at last, Daniel came in before me, whose name was Belteshazzar according to the name of my god, and in whom is the spirit of the holy gods. I told the dream before him, saying,", "zh": "末後那照我神的名，稱為伯提沙撒的但以理來到我面前，他裏頭有聖神的靈，我將夢告訴他說：", "ja": "最後にダニエルがわたしの前にきた、――彼の名はわが神の名にちなんで、ベルテシャザルととなえられ、彼のうちには聖なる神の霊がやどっていた――わたしは彼にその夢を語って言った、"}, "9": {"en": "“Belteshazzar, master of the magicians, because I know that the spirit of the holy gods is in you and no secret troubles you, tell me the visions of my dream that I have seen, and its interpretation.", "zh": "『術士的領袖伯提沙撒啊，因我知道你裏頭有聖神的靈，甚麼奧祕的事都不能使你為難。現在要把我夢中所見的異象和夢的講解告訴我。』", "ja": "「博士の長ベルテシャザルよ、わたしは知っている。聖なる神の霊があなたのうちにやどっているから、どんな秘密もあなたにはむずかしいことはない。ここにわたしが見た夢がある。その解き明かしをわたしに告げなさい。"}, "10": {"en": "These were the visions of my head on my bed: I saw, and behold, a tree in the middle of the earth; and its height was great.", "zh": "「我在床上腦中的異象是這樣：我看見地當中有一棵樹，極其高大。", "ja": "わたしが床にあって見た脳中の幻はこれである。わたしが見たのに、地の中央に一本の木があって、そのたけが高かったが、"}, "11": {"en": "The tree grew and was strong. Its height reached to the sky and its sight to the end of all the earth.", "zh": "那樹漸長，而且堅固，高得頂天，從地極都能看見，", "ja": "その木は成長して強くなり、天に達するほどの高さになって、地の果までも見えわたり、"}, "12": {"en": "Its leaves were beautiful, and it had much fruit, and in it was food for all. The animals of the field had shade under it, and the birds of the sky lived in its branches, and all flesh was fed from it.", "zh": "葉子華美，果子甚多，可作眾生的食物；田野的走獸臥在蔭下，天空的飛鳥宿在枝上；凡有血氣的都從這樹得食。", "ja": "その葉は美しく、その実は豊かで、すべての者がその中から食物を獲、また野の獣はその陰にやどり、空の鳥はその枝にすみ、すべての肉なる者はこれによって養われた。"}, "13": {"en": "“I saw in the visions of my head on my bed, and behold, a holy watcher came down from the sky.", "zh": "「我在床上腦中的異象，見有一位守望的聖者從天而降。", "ja": "わたしが床にあって見た脳中の幻の中に、ひとりの警護者、ひとりの聖者の天から下るのを見たが、"}, "14": {"en": "He cried aloud and said this: ‘Cut down the tree, and cut off its branches! Shake off its leaves and scatter its fruit! Let the animals get away from under it and the birds from its branches.", "zh": "大聲呼叫說：『伐倒這樹！砍下枝子！搖掉葉子！拋散果子！使走獸離開樹下，飛鳥躲開樹枝。", "ja": "彼は声高く呼ばわって、こう言った、『この木を切り倒し、その枝を切りはらい、その葉をゆり落し、その実を打ち散らし、獣をその下から逃げ去らせ、鳥をその枝から飛び去らせよ。"}, "15": {"en": "Nevertheless leave the stump of its roots in the earth, even with a band of iron and bronze, in the tender grass of the field; and let it be wet with the dew of the sky. Let his portion be with the animals in the grass of the earth.", "zh": "樹墩卻要留在地內，用鐵圈和銅圈箍住，在田野的青草中讓天露滴濕，使他與地上的獸一同吃草，", "ja": "ただしその根の切り株を地に残し、それに鉄と青銅のなわをかけて、野の若草の中におき、天からくだる露にぬれさせ、また地の草の中で、獣と共にその分にあずからせよ。"}, "16": {"en": "Let his heart be changed from man’s, and let an animal’s heart be given to him. Then let seven times pass over him.", "zh": "使他的心改變，不如人心，給他一個獸心，使他經過七期。", "ja": "またその心は変って人間の心のようでなく、獣の心が与えられて、七つの時を過ごさせよ。"}, "17": {"en": "“ ‘The sentence is by the decree of the watchers and the demand by the word of the holy ones, to the intent that the living may know that the Most High rules in the kingdom of men, and gives it to whomever he will, and sets up over it the lowest of men.’", "zh": "這是守望者所發的命，聖者所出的令，好叫世人知道至高者在人的國中掌權，要將國賜與誰就賜與誰，或立極卑微的人執掌國權。』", "ja": "この宣言は警護者たちの命令によるもの、この決定は聖者たちの言葉によるもので、いと高き者が、人間の国を治めて、自分の意のままにこれを人に与え、また人のうちの最も卑しい者を、その上に立てられるという事を、すべての者に知らせるためである』と。"}, "18": {"en": "“This dream I, King Nebuchadnezzar, have seen; and you, Belteshazzar, declare the interpretation, because all the wise men of my kingdom are not able to make known to me the interpretation; but you are able, for the spirit of the holy gods is in you.”", "zh": "「這是我－尼布甲尼撒王所做的夢。伯提沙撒啊，你要說明這夢的講解；因為我國中的一切哲士都不能將夢的講解告訴我，惟獨你能，因你裏頭有聖神的靈。」", "ja": "われネブカデネザル王はこの夢を見た。ベルテシャザルよ、あなたはその解き明かしをわたしに告げなさい。わが国の知者たちは、いずれもその解き明かしを、わたしに示すことができなかったけれども、あなたにはそれができる。あなたのうちには、聖なる神の霊がやどっているからだ」。"}, "19": {"en": "Then Daniel, whose name was Belteshazzar, was stricken mute for a while, and his thoughts troubled him. The king answered, “Belteshazzar, don’t let the dream or the interpretation, trouble you.”", "zh": "於是稱為伯提沙撒的但以理驚訝片時，心意驚惶。王說：「伯提沙撒啊，不要因夢和夢的講解驚惶。」伯提沙撒回答說：「我主啊，願這夢歸與恨惡你的人，講解歸與你的敵人。", "ja": "その時、その名をベルテシャザルととなえるダニエルは、しばらくのあいだ驚き、思い悩んだので、王は彼に告げて言った、「ベルテシャザルよ、あなたはこの夢と、その解き明かしのために、悩むには及ばない」。ベルテシャザルは答えて言った、「わが主よ、どうか、この夢は、あなたを憎む者にかかわるように。この解き明かしは、あなたの敵に臨むように。"}, "20": {"en": "Belteshazzar answered, “My lord, may the dream be for those who hate you, and its interpretation to your adversaries.   The tree that you saw, which grew and was strong, whose height reached to the sky and its sight to all the earth;", "zh": "你所見的樹漸長，而且堅固，高得頂天，從地極都能看見；", "ja": "あなたが見られた木、すなわちその成長して強くなり、天に達するほどの高さになって、地の果までも見えわたり、"}, "21": {"en": "whose leaves were beautiful and its fruit plentiful, and in it was food for all; under which the animals of the field lived, and on whose branches the birds of the sky had their habitation—", "zh": "葉子華美，果子甚多，可作眾生的食物；田野的走獸住在其下；天空的飛鳥宿在枝上。", "ja": "その葉は美しく、その実は豊かで、すべての者がその中から食物を獲、また野の獣がその陰にやどり、空の鳥がその枝に住んだ木、"}, "22": {"en": "it is you, O king, that have grown and become strong; for your greatness has grown, and reaches to the sky, and your dominion to the end of the earth.", "zh": "「王啊，這漸長又堅固的樹就是你。你的威勢漸長及天，你的權柄管到地極。", "ja": "王よ、それはすなわちあなたです。あなたは成長して強くなり、天に達するほどに大きくなり、あなたの主権は地の果にまで及びました。"}, "23": {"en": "“Whereas the king saw a holy watcher coming down from the sky and saying, ‘Cut down the tree, and destroy it; nevertheless leave the stump of its roots in the earth, even with a band of iron and bronze, in the tender grass of the field, and let it be wet with the dew of the sky. Let his portion be with the animals of the field, until seven times pass over him.’", "zh": "王既看見一位守望的聖者從天而降，說：『將這樹砍伐毀壞，樹墩卻要留在地內，用鐵圈和銅圈箍住；在田野的青草中，讓天露滴濕，使他與地上的獸一同吃草，直到經過七期。』", "ja": "ところが、王はひとりの警護者、ひとりの聖者が、天から下って、こう言うのを見られました、『この木を切り倒して、これを滅ぼせ。ただしその根の切り株を地に残し、それに鉄と青銅のなわをかけて、野の若草の中におき、天からくだる露にぬれさせ、また野の獣と共にその分にあずからせて、七つの時を過ごさせよ』と。"}, "24": {"en": "“This is the interpretation, O king, and it is the decree of the Most High, which has come on my lord the king:", "zh": "「王啊，講解就是這樣：臨到我主我王的事是出於至高者的命。", "ja": "王よ、その解き明かしはこうです。すなわちこれはいと高き者の命令であって、わが主なる王に臨まんとするものです。"}, "25": {"en": "You will be driven from men and your dwelling shall be with the animals of the field. You will be made to eat grass as oxen, and will be wet with the dew of the sky, and seven times shall pass over you, until you know that the Most High rules in the kingdom of men, and gives it to whomever he will.", "zh": "你必被趕出離開世人，與野地的獸同居，吃草如牛，被天露滴濕，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。", "ja": "すなわちあなたは追われて世の人を離れ、野の獣と共におり、牛のように草を食い、天からくだる露にぬれるでしょう。こうして七つの時が過ぎて、ついにあなたは、いと高き者が人間の国を治めて、自分の意のままに、これを人に与えられることを知るに至るでしょう。"}, "26": {"en": "Whereas it was commanded to leave the stump of the roots of the tree, your kingdom shall be sure to you after you know that Heaven rules.", "zh": "守望者既吩咐存留樹墩，等你知道諸天掌權，以後你的國必定歸你。", "ja": "また彼らはその木の根の切り株を残しおけと命じたので、あなたが、天はまことの支配者であるということを知った後、あなたの国はあなたに確保されるでしょう。"}, "27": {"en": "Therefore, O king, let my counsel be acceptable to you, and break off your sins by righteousness, and your iniquities by showing mercy to the poor. Perhaps there may be a lengthening of your tranquility.”", "zh": "王啊，求你悅納我的諫言，以施行公義斷絕罪過，以憐憫窮人除掉罪孽，或者你的平安可以延長。」", "ja": "それゆえ王よ、あなたはわたしの勧告をいれ、義を行って罪を離れ、しえたげられる者をあわれんで、不義を離れなさい。そうすれば、あるいはあなたの繁栄が、長く続くかもしれません」。"}, "28": {"en": "All this came on the King Nebuchadnezzar.", "zh": "這事都臨到尼布甲尼撒王。", "ja": "この事は皆ネブカデネザル王に臨んだ。"}, "29": {"en": "At the end of twelve months he was walking in the royal palace of Babylon.", "zh": "過了十二個月，他遊行在巴比倫王宮裏。", "ja": "十二か月を経て後、王がバビロンの王宮の屋上を歩いていたとき、"}, "30": {"en": "The king spoke and said, “Is not this great Babylon, which I have built for the royal dwelling place by the might of my power and for the glory of my majesty?”", "zh": "他說：「這大巴比倫不是我用大能大力建為京都，要顯我威嚴的榮耀嗎？」", "ja": "王は自ら言った、「この大いなるバビロンは、わたしの大いなる力をもって建てた王城であって、わが威光を輝かすものではないか」。"}, "31": {"en": "While the word was in the king’s mouth, a voice came from the sky, saying, “O King Nebuchadnezzar, to you it is spoken: ‘The kingdom has departed from you.", "zh": "這話在王口中尚未說完，有聲音從天降下，說：「尼布甲尼撒王啊，有話對你說，你的國位離開你了。", "ja": "その言葉がなお王の口にあるうちに、天から声がくだって言った、「ネブカデネザル王よ、あなたに告げる。国はあなたを離れ去った。"}, "32": {"en": "You shall be driven from men, and your dwelling shall be with the animals of the field. You shall be made to eat grass like oxen. Seven times shall pass over you, until you know that the Most High rules in the kingdom of men, and gives it to whomever he will.’ ”", "zh": "你必被趕出離開世人，與野地的獸同居，吃草如牛，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。」", "ja": "あなたは、追われて世の人を離れ、野の獣と共におり、牛のように草を食い、こうして七つの時を経て、ついにあなたは、いと高き者が人間の国を治めて、自分の意のままに、これを人に与えられることを知るに至るだろう」。"}, "33": {"en": "This was fulfilled the same hour on Nebuchadnezzar. He was driven from men and ate grass like oxen; and his body was wet with the dew of the sky until his hair had grown like eagles’ feathers, and his nails like birds’ claws.", "zh": "當時這話就應驗在尼布甲尼撒的身上，他被趕出離開世人，吃草如牛，身被天露滴濕，頭髮長長，好像鷹毛；指甲長長，如同鳥爪。", "ja": "この言葉は、ただちにネブカデネザルに成就した。彼は追われて世の人を離れ、牛のように草を食い、その身は天からくだる露にぬれ、ついにその毛は、わしの羽のようになり、そのつめは鳥のつめのようになった。"}, "34": {"en": "At the end of the days I, Nebuchadnezzar, lifted up my eyes to heaven, and my understanding returned to me; and I blessed the Most High, and I praised and honored him who lives forever, for his dominion is an everlasting dominion, and his kingdom from generation to generation.", "zh": "日子滿足，我－尼布甲尼撒舉目望天，我的聰明復歸於我，我便稱頌至高者，讚美尊敬活到永遠的上帝。 他的權柄是永有的； 他的國存到萬代。", "ja": "こうしてその期間が満ちた後、われネブカデネザルは、目をあげて天を仰ぎ見ると、わたしの理性が自分に帰ったので、わたしはいと高き者をほめ、その永遠に生ける者をさんびし、かつあがめた。その主権は永遠の主権、その国は世々かぎりなく、"}, "35": {"en": "All the inhabitants of the earth are reputed as nothing; and he does according to his will in the army of heaven, and among the inhabitants of the earth; and no one can stop his hand, or ask him, “What are you doing?”", "zh": "世上所有的居民都算為虛無； 在天上的萬軍和世上的居民中， 他都憑自己的意旨行事。 無人能攔住他手， 或問他說，你做甚麼呢？", "ja": "地に住む民はすべて無き者のように思われ、天の衆群にも、地に住む民にも、彼はその意のままに事を行われる。だれも彼の手をおさえて「あなたは何をするのか」と言いうる者はない。"}, "36": {"en": "At the same time my understanding returned to me; and for the glory of my kingdom, my majesty and brightness returned to me. My counselors and my lords sought me; and I was established in my kingdom, and excellent greatness was added to me.", "zh": "那時，我的聰明復歸於我，為我國的榮耀、威嚴，和光耀也都復歸於我；並且我的謀士和大臣也來朝見我。我又得堅立在國位上，至大的權柄加增於我。", "ja": "この時わたしの理性は自分に帰り、またわが国の光栄のために、わが尊厳と光輝とが、わたしに帰った。わが大臣、わが貴族らもきて、わたしに求め、わたしは国の上に堅く立って、前にもまさって大いなる者となった。"}, "37": {"en": "Now I, Nebuchadnezzar, praise and extol and honor the King of heaven; for all his works are truth, and his ways justice; and those who walk in pride he is able to abase.", "zh": "現在我－尼布甲尼撒讚美、尊崇、恭敬天上的王；因為他所做的全都誠實，他所行的也都公平。那行動驕傲的，他能降為卑。", "ja": "そこでわれネブカデネザルは今、天の王をほめたたえ、かつあがめたてまつる。そのみわざはことごとく真実で、その道は正しく、高ぶり歩む者を低くされる。"}}}, "5": {"verses": {"1": {"en": "Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand.", "zh": "伯沙撒王為他的一千大臣設擺盛筵，與這一千人對面飲酒。", "ja": "ベルシャザル王は、その大臣一千人のために、盛んな酒宴を設け、その一千人の前で酒を飲んでいた。"}, "2": {"en": "Belshazzar, while he tasted the wine, commanded that the golden and silver vessels which Nebuchadnezzar his father had taken out of the temple which was in Jerusalem be brought to him, that the king and his lords, his wives and his concubines, might drink from them.", "zh": "伯沙撒歡飲之間，吩咐人將他父尼布甲尼撒從耶路撒冷殿中所掠的金銀器皿拿來，王與大臣、皇后、妃嬪好用這器皿飲酒。", "ja": "酒が進んだとき、ベルシャザルは、その父ネブカデネザルがエルサレムの神殿から取ってきた金銀の器を持ってこいと命じた。王とその大臣たち、および王の妻とそばめらが、これをもって酒を飲むためであった。"}, "3": {"en": "Then they brought the golden vessels that were taken out of the temple of God’s house which was at Jerusalem; and the king and his lords, his wives and his concubines, drank from them.", "zh": "於是他們把耶路撒冷上帝殿庫房中所掠的金器皿拿來，王和大臣、皇后、妃嬪就用這器皿飲酒。", "ja": "そこで人々はそのエルサレムの神の宮すなわち神殿から取ってきた金銀の器を持ってきたので、王とその大臣たち、および王の妻とそばめらは、これをもって飲んだ。"}, "4": {"en": "They drank wine, and praised the gods of gold, and of silver, of bronze, of iron, of wood, and of stone.", "zh": "他們飲酒，讚美金、銀、銅、鐵、木、石所造的神。", "ja": "すなわち彼らは酒を飲んで、金、銀、青銅、鉄、木、石などの神々をほめたたえた。"}, "5": {"en": "In the same hour, the fingers of a man’s hand came out and wrote near the lamp stand on the plaster of the wall of the king’s palace. The king saw the part of the hand that wrote.", "zh": "當時，忽有人的指頭顯出，在王宮與燈臺相對的粉牆上寫字。王看見寫字的指頭", "ja": "すると突然人の手の指があらわれて、燭台と相対する王の宮殿の塗り壁に物を書いた。王はその物を書いた手の先を見た。"}, "6": {"en": "Then the king’s face was changed in him, and his thoughts troubled him; and the joints of his thighs were loosened, and his knees struck one against another.", "zh": "就變了臉色，心意驚惶，腰骨好像脫節，雙膝彼此相碰，", "ja": "そのために王の顔色は変り、その心は思い悩んで乱れ、その腰のつがいはゆるみ、ひざは震えて互に打ちあった。"}, "7": {"en": "The king cried aloud to bring in the enchanters, the Chaldeans, and the soothsayers. The king spoke and said to the wise men of Babylon, “Whoever reads this writing and shows me its interpretation shall be clothed with purple, and have a chain of gold about his neck, and shall be the third ruler in the kingdom.”", "zh": "大聲吩咐將用法術的和迦勒底人並觀兆的領進來，對巴比倫的哲士說，誰能讀這文字，把講解告訴我，他必身穿紫袍，項帶金鍊，在我國中位列第三。", "ja": "王は大声に呼ばわって、法術士、カルデヤびと、占い師らを召してこさせた。王はバビロンの知者たちに告げて言った、「この文字を読み、その解き明かしをわたしに示す者には紫の衣を着せ、首に金の鎖をかけさせて、国の第三のつかさとしよう」と。"}, "8": {"en": "Then all the king’s wise men came in; but they could not read the writing, and couldn’t make known to the king the interpretation.", "zh": "於是王的一切哲士都進來，卻不能讀那文字，也不能把講解告訴王。", "ja": "王の知者たちは皆はいってきた。しかしその文字を読むことができず、またその解き明かしを王に示すことができなかったので、"}, "9": {"en": "Then King Belshazzar was greatly troubled, and his face was changed in him, and his lords were perplexed.", "zh": "伯沙撒王就甚驚惶，臉色改變，他的大臣也都驚奇。", "ja": "ベルシャザル王は大いに思い悩んで、その顔色は変り、王の大臣たちも当惑した。"}, "10": {"en": "The queen by reason of the words of the king and his lords came into the banquet house. The queen spoke and said, “O king, live forever; don’t let your thoughts trouble you, nor let your face be changed.", "zh": "太后因王和他大臣所說的話，就進入宴宮，說：「願王萬歲！你心意不要驚惶，臉面不要變色。", "ja": "時に王妃は王と大臣たちの言葉を聞いて、その宴会場にはいってきた。そして王妃は言った、「王よ、どうか、とこしえに生きながらえられますように。あなたは心に思い悩んではなりません。また顔色を変えるには及びません。"}, "11": {"en": "There is a man in your kingdom in whom is the spirit of the holy gods; and in the days of your father, light and understanding and wisdom, like the wisdom of the gods, were found in him. The king, Nebuchadnezzar, your father—yes, the king, your father—made him master of the magicians, enchanters, Chaldeans, and soothsayers,", "zh": "在你國中有一人，他裏頭有聖神的靈，你父在世的日子，這人心中光明，又有聰明智慧，好像神的智慧。你父尼布甲尼撒王，就是王的父，立他為術士、用法術的，和迦勒底人，並觀兆的領袖。", "ja": "あなたの国には、聖なる神の霊のやどっているひとりの人がおります。あなたの父の代に、彼は、明知、分別および神のような知恵のあることをあらわしました。あなたの父ネブカデネザル王は、彼を立てて、博士、法術士、カルデヤびと、占い師らの長とされました。"}, "12": {"en": "because an excellent spirit, knowledge, understanding, interpreting of dreams, showing of dark sentences, and dissolving of doubts were found in the same Daniel, whom the king named Belteshazzar. Now let Daniel be called, and he will show the interpretation.”", "zh": "在他裏頭有美好的靈性，又有知識聰明，能圓夢，釋謎語，解疑惑。這人名叫但以理，尼布甲尼撒王又稱他為伯提沙撒，現在可以召他來，他必解明這意思。」", "ja": "彼は、王がベルテシャザルという名を与えたダニエルという者ですが、このダニエルには、すぐれた霊、知識、分別があって、夢を解き、なぞを解き、難問を解くことができます。ゆえにダニエルを召しなさい。彼はその解き明かしを示すでしょう」。"}, "13": {"en": "Then Daniel was brought in before the king. The king spoke and said to Daniel, “Are you that Daniel of the children of the captivity of Judah, whom the king my father brought out of Judah?", "zh": "但以理就被領到王前。王問但以理說：「你是被擄之猶大人中的但以理嗎？就是我父王從猶大擄來的嗎？", "ja": "そこでダニエルは王の前に召された。王はダニエルに言った、「あなたは、わが父の王が、ユダからひきつれてきたユダの捕囚のひとりなのか。"}, "14": {"en": "I have heard of you, that the spirit of the gods is in you and that light, understanding, and excellent wisdom are found in you.", "zh": "我聽說你裏頭有神的靈，心中光明，又有聰明和美好的智慧。", "ja": "聞くところによると、あなたのうちには、聖なる神の霊がやどっていて、明知、分別および非凡な知恵があるそうだ。"}, "15": {"en": "Now the wise men, the enchanters, have been brought in before me, that they should read this writing, and make known to me its interpretation; but they could not show the interpretation of the thing.", "zh": "現在哲士和用法術的都領到我面前，為叫他們讀這文字，把講解告訴我，無奈他們都不能把講解說出來。", "ja": "わたしは、知者、法術士らを、わが前に召しよせて、この文字を読ませ、その解き明かしを示させようとしたが、彼らは、この事の解き明かしを示すことができなかった。"}, "16": {"en": "But I have heard of you, that you can give interpretations and dissolve doubts. Now if you can read the writing and make known to me its interpretation, you shall be clothed with purple, and have a chain of gold around your neck, and shall be the third ruler in the kingdom.”", "zh": "我聽說你善於講解，能解疑惑；現在你若能讀這文字，把講解告訴我，就必身穿紫袍，項戴金鍊，在我國中位列第三。」", "ja": "しかしまた聞くところによると、あなたは解き明かしをなし、かつ難問を解くことができるそうだ。それで、あなたがもし、この文字を読み、その解き明かしをわたしに示すことができたなら、あなたに紫の衣を着せ、金の鎖を首にかけさせて、この国の第三のつかさとしよう」。"}, "17": {"en": "Then Daniel answered before the king, “Let your gifts be to yourself, and give your rewards to another. Nevertheless, I will read the writing to the king, and make known to him the interpretation.", "zh": "但以理在王面前回答說：「你的贈品可以歸你自己，你的賞賜可以歸給別人；我卻要為王讀這文字，把講解告訴王。", "ja": "ダニエルは王の前に答えて言った、「あなたの賜物は、あなたご自身にとっておき、あなたの贈り物は、他人にお与えください。それでも、わたしは王のためにその文字を読み、その解き明かしをお知らせいたしましょう。"}, "18": {"en": "“To you, king, the Most High God gave Nebuchadnezzar your father the kingdom, and greatness, and glory, and majesty.", "zh": "王啊，至高的上帝曾將國位、大權、榮耀、威嚴賜與你父尼布甲尼撒；", "ja": "王よ、いと高き神はあなたの父ネブカデネザルに国と権勢と、光栄と尊厳とを賜いました。"}, "19": {"en": "Because of the greatness that he gave him, all the peoples, nations, and languages trembled and feared before him. He killed whom he wanted to, and he kept alive whom he wanted to. He raised up whom he wanted to, and he put down whom he wanted to.", "zh": "因上帝所賜他的大權，各方、各國、各族的人都在他面前戰兢恐懼。他可以隨意生殺，隨意升降。", "ja": "彼に権勢を賜わったことによって、諸民、諸族、諸国語の者はみな、彼の前におののき恐れました。彼は自分の欲する者を殺し、自分の欲する者を生かし、自分の欲する者を上げ、自分の欲する者を下しました。"}, "20": {"en": "But when his heart was lifted up, and his spirit was hardened so that he dealt proudly, he was deposed from his kingly throne, and they took his glory from him.", "zh": "但他心高氣傲，靈也剛愎，甚至行事狂傲，就被革去王位，奪去榮耀。", "ja": "しかし彼は心に高ぶり、かたくなになり、ごうまんにふるまったので、王位からしりぞけられ、その光栄を奪われ、"}, "21": {"en": "He was driven from the sons of men, and his heart was made like the animals’, and his dwelling was with the wild donkeys. He was fed with grass like oxen, and his body was wet with the dew of the sky, until he knew that the Most High God rules in the kingdom of men, and that he sets up over it whomever he will.", "zh": "他被趕出離開世人，他的心變如獸心，與野驢同居，吃草如牛，身被天露滴濕，等他知道至高的上帝在人的國中掌權，憑自己的意旨立人治國。", "ja": "追われて世の人と離れ、その思いは獣のようになり、そのすまいは野ろばと共にあり、牛のように草を食い、その身は天からくだる露にぬれ、こうしてついに彼は、いと高き神が人間の国を治めて、自分の意のままに人を立てられるということを、知るようになりました。"}, "22": {"en": "“You, his son, Belshazzar, have not humbled your heart, though you knew all this,", "zh": "伯沙撒啊，你是他的兒子，你雖知道這一切，你心仍不自卑，", "ja": "ベルシャザルよ、あなたは彼の子であって、この事をことごとく知っていながら、なお心を低くせず、"}, "23": {"en": "but have lifted up yourself against the Lord of heaven; and they have brought the vessels of his house before you, and you and your lords, your wives, and your concubines, have drunk wine from them. You have praised the gods of silver and gold, of bronze, iron, wood, and stone, which don’t see, or hear, or know; and you have not glorified the God in whose hand your breath is, and whose are all your ways.", "zh": "竟向天上的主自高，使人將他殿中的器皿拿到你面前，你和大臣、皇后、妃嬪用這器皿飲酒。你又讚美那不能看、不能聽、無知無識、金、銀、銅、鐵、木、石所造的神，卻沒有將榮耀歸與那手中有你氣息，管理你一切行動的上帝。", "ja": "かえって天の主にむかって、みずから高ぶり、その宮の器物をあなたの前に持ってこさせ、あなたとあなたの大臣たちと、あなたの妻とそばめたちは、それをもって酒を飲み、そしてあなたは見ることも、聞くことも、物を知ることもできない金、銀、青銅、鉄、木、石の神々をほめたたえたが、あなたの命をその手ににぎり、あなたのすべての道をつかさどられる神をあがめようとはしなかった。"}, "24": {"en": "Then the part of the hand was sent from before him, and this writing was inscribed.", "zh": "因此從上帝那裏顯出指頭來寫這文字。", "ja": "それゆえ、彼の前からこの手が出てきて、この文字が書きしるされたのです。"}, "25": {"en": "“This is the writing that was inscribed: ‘MENE, MENE, TEKEL, UPHARSIN.’", "zh": "「所寫的文字是：『彌尼，彌尼，提客勒，烏法珥新。』", "ja": "そのしるされた文字はこうです。メネ、メネ、テケル、ウパルシン。"}, "26": {"en": "“This is the interpretation of the thing: MENE: God has counted your kingdom, and brought it to an end.", "zh": "講解是這樣：彌尼，就是上帝已經數算你國的年日到此完畢。", "ja": "その事の解き明かしはこうです、メネは神があなたの治世を数えて、これをその終りに至らせたことをいうのです。"}, "27": {"en": "TEKEL: you are weighed in the balances, and are found wanting.", "zh": "提客勒，就是你被稱在天平裏，顯出你的虧欠。", "ja": "テケルは、あなたがはかりで量られて、その量の足りないことがあらわれたことをいうのです。"}, "28": {"en": "PERES: your kingdom is divided, and given to the Medes and Persians.”", "zh": "毗勒斯，就是你的國分裂，歸與米底亞人和波斯人。」", "ja": "ペレスは、あなたの国が分かたれて、メデアとペルシャの人々に与えられることをいうのです」。"}, "29": {"en": "Then Belshazzar commanded, and they clothed Daniel with purple, and put a chain of gold about his neck, and made proclamation concerning him, that he should be the third ruler in the kingdom.", "zh": "伯沙撒下令，人就把紫袍給但以理穿上，把金鍊給他戴在頸項上，又傳令使他在國中位列第三。", "ja": "そこでベルシャザルは命じて、ダニエルに紫の衣を着せ、金の鎖をその首にかけさせ、彼について布告を発して、彼は国の第三のつかさであると言わせた。"}, "30": {"en": "In that night Belshazzar the Chaldean King was slain.", "zh": "當夜，迦勒底王伯沙撒被殺。", "ja": "カルデヤびとの王ベルシャザルは、その夜のうちに殺され、"}, "31": {"en": "Darius the Mede received the kingdom, being about sixty-two years old.", "zh": "米底亞人大流士年六十二歲，取了迦勒底國。", "ja": "メデアびとダリヨスが、その国を受けた。この時ダリヨスは、おおよそ六十二歳であった。"}}}, "6": {"verses": {"1": {"en": "It pleased Darius to set over the kingdom one hundred twenty local governors, who should be throughout the whole kingdom;", "zh": "大流士隨心所願，立一百二十個總督，治理通國。", "ja": "ダリヨスは全国を治めるために、その国に百二十人の総督を立てることをよしとし、"}, "2": {"en": "and over them three presidents, of whom Daniel was one, that these local governors might give account to them, and that the king should suffer no loss.", "zh": "又在他們以上立總長三人（但以理在其中），使總督在他們三人面前回覆事務，免得王受虧損。", "ja": "また彼らの上に三人の総監を立てた。ダニエルはそのひとりであった。これは総督たちをして、この三人の前に、その職務に関する報告をさせて、王に損失の及ぶことのないようにするためであった。"}, "3": {"en": "Then this Daniel was distinguished above the presidents and the local governors, because an excellent spirit was in him; and the king thought to set him over the whole realm.", "zh": "因這但以理有美好的靈性，所以顯然超乎其餘的總長和總督，王又想立他治理通國。", "ja": "ダニエルは彼のうちにあるすぐれた霊のゆえに、他のすべての総監および総督たちにまさっていたので、王は彼を立てて全国を治めさせようとした。"}, "4": {"en": "Then the presidents and the local governors sought to find occasion against Daniel as touching the kingdom; but they could find no occasion or fault, because he was faithful. There wasn’t any error or fault found in him.", "zh": "那時，總長和總督尋找但以理誤國的把柄，為要參他；只是找不着他的錯誤過失，因他忠心辦事，毫無錯誤過失。", "ja": "そこで総監および総督らは、国事についてダニエルを訴えるべき口実を得ようとしたが、訴えるべきなんの口実も、なんのとがをも見いだすことができなかった。それは彼が忠信な人であって、その身になんのあやまちも、とがも見いだされなかったからである。"}, "5": {"en": "Then these men said, “We won’t find any occasion against this Daniel, unless we find it against him concerning the law of his God.”", "zh": "那些人便說：「我們要找參這但以理的把柄，除非在他上帝的律法中就尋不着。」", "ja": "そこでその人々は言った、「われわれはダニエルの神の律法に関して、彼を訴える口実を得るのでなければ、ついに彼を訴えることはできまい」と。"}, "6": {"en": "Then these presidents and local governors assembled together to the king, and said this to him, “King Darius, live forever!", "zh": "於是，總長和總督紛紛聚集來見王，說：「願大流士王萬歲！", "ja": "こうして総監と総督らは、王のもとに集まってきて、王に言った、「ダリヨス王よ、どうかとこしえに生きながらえられますように。"}, "7": {"en": "All the presidents of the kingdom, the deputies and the local governors, the counselors and the governors, have consulted together to establish a royal statute and to make a strong decree, that whoever asks a petition of any god or man for thirty days, except of you, O king, he shall be cast into the den of lions.", "zh": "國中的總長、欽差、總督、謀士，和巡撫彼此商議，要立一條堅定的禁令，三十日內，不拘何人，若在王以外，或向神或向人求甚麼，就必扔在獅子坑中。", "ja": "国の総監、長官および総督、参議および知事らは、相はかって、王が一つのおきてを立て、一つの禁令を定められるよう求めることになりました。王よ、それはこうです。すなわち今から三十日の間は、ただあなたにのみ願い事をさせ、もしあなたをおいて、神または人にこれをなす者があれば、すべてその者を、ししの穴に投げ入れるというのです。"}, "8": {"en": "Now, O king, establish the decree and sign the writing, that it not be changed, according to the law of the Medes and Persians, which doesn’t alter.”", "zh": "王啊，現在求你立這禁令，加蓋玉璽，使禁令決不更改；照米底亞和波斯人的例是不可更改的。」", "ja": "それで王よ、その禁令を定め、その文書に署名して、メデアとペルシャの変ることのない法律のごとく、これを変えることのできないようにしてください」。"}, "9": {"en": "Therefore King Darius signed the writing and the decree.", "zh": "於是大流士王立這禁令，加蓋玉璽。", "ja": "そこでダリヨス王は、その禁令の文書に署名した。"}, "10": {"en": "When Daniel knew that the writing was signed, he went into his house (now his windows were open in his room toward Jerusalem) and he kneeled on his knees three times a day, and prayed, and gave thanks before his God, as he did before.", "zh": "但以理知道這禁令蓋了玉璽，就到自己家裏（他樓上的窗戶開向耶路撒冷），一日三次，雙膝跪在他上帝面前，禱告感謝，與素常一樣。", "ja": "ダニエルは、その文書の署名されたことを知って家に帰り、二階のへやの、エルサレムに向かって窓の開かれた所で、以前からおこなっていたように、一日に三度ずつ、ひざをかがめて神の前に祈り、かつ感謝した。"}, "11": {"en": "Then these men assembled together, and found Daniel making petition and supplication before his God.", "zh": "那些人就紛紛聚集，見但以理在他上帝面前祈禱懇求。", "ja": "そこでその人々は集まってきて、ダニエルがその神の前に祈り、かつ求めていることを見たので、"}, "12": {"en": "Then they came near, and spoke before the king concerning the king’s decree: “Haven’t you signed a decree that every man who makes a petition to any god or man within thirty days, except to you, O king, shall be cast into the den of lions?” The king answered, “This thing is true, according to the law of the Medes and Persians, which doesn’t alter.”", "zh": "他們便進到王前，提王的禁令，說：「王啊，三十日內不拘何人，若在王以外，或向神或向人求甚麼，必被扔在獅子坑中。王不是在這禁令上蓋了玉璽嗎？」王回答說：「實有這事，照米底亞和波斯人的例是不可更改的。」", "ja": "彼らは王の前にきて、王の禁令について奏上して言った、「王よ、あなたは禁令に署名して、今から三十日の間は、ただあなたにのみ願い事をさせ、もしあなたをおいて、神または人に、これをなす者があれば、すべてその者を、ししの穴に投げ入れると、定められたではありませんか」。王は答えて言った、「その事は確かであって、メデアとペルシャの法律のごとく、変えることのできないものだ」。"}, "13": {"en": "Then they answered and said before the king, “That Daniel, who is of the children of the captivity of Judah, doesn’t respect you, O king, nor the decree that you have signed, but makes his petition three times a day.”", "zh": "他們對王說：「王啊，那被擄之猶大人中的但以理不理你，也不遵你蓋了玉璽的禁令，他竟一日三次祈禱。」", "ja": "彼らは王の前に答えて言った、「王よ、ユダから引いてきた捕囚のひとりである、かのダニエルは、あなたをも、あなたの署名された禁令をも顧みず、一日に三度ずつ、祈をささげています」。"}, "14": {"en": "Then the king, when he heard these words, was very displeased, and set his heart on Daniel to deliver him; and he labored until the going down of the sun to rescue him.", "zh": "王聽見這話，就甚愁煩，一心要救但以理，籌劃解救他，直到日落的時候。", "ja": "王はこの言葉を聞いて大いに憂え、ダニエルを救おうと心を用い、日の入るまで、彼を救い出すことに努めた。"}, "15": {"en": "Then these men assembled together to the king, and said to the king, “Know, O king, that it is a law of the Medes and Persians, that no decree nor statute which the king establishes may be changed.”", "zh": "那些人就紛紛聚集來見王，說：「王啊，當知道米底亞人和波斯人有例，凡王所立的禁令和律例都不可更改。」", "ja": "時にその人々は、また王のもとに集まってきて、王に言った、「王よ、メデアとペルシャの法律によれば、王の立てた禁令、または、おきては変えることのできないものであることを、ご承知ください」。"}, "16": {"en": "Then the king commanded, and they brought Daniel and cast him into the den of lions. The king spoke and said to Daniel, “Your God whom you serve continually, he will deliver you.”", "zh": "王下令，人就把但以理帶來，扔在獅子坑中。王對但以理說：「你所常事奉的上帝，他必救你。」", "ja": "そこで王は命令を下したので、ダニエルは引き出されて、ししの穴に投げ入れられた。王はダニエルに言った、「どうか、あなたの常に仕える神が、あなたを救われるように」。"}, "17": {"en": "A stone was brought, and laid on the mouth of the den; and the king sealed it with his own signet, and with the signet of his lords; that nothing might be changed concerning Daniel.", "zh": "有人搬石頭放在坑口，王用自己的璽和大臣的印，封閉那坑，使懲辦但以理的事毫無更改。", "ja": "そして一つの石を持ってきて、穴の口をふさいだので、王は自分の印と、大臣らの印をもって、これに封印した。これはダニエルの処置を変えることのないようにするためであった。"}, "18": {"en": "Then the king went to his palace, and passed the night fasting. No musical instruments were brought before him; and his sleep fled from him.", "zh": "王回宮，終夜禁食，無人拿樂器到他面前，並且睡不着覺。", "ja": "こうして王はその宮殿に帰ったが、その夜は食をとらず、また、そばめたちを召し寄せず、全く眠ることもしなかった。"}, "19": {"en": "Then the king arose very early in the morning, and went in haste to the den of lions.", "zh": "次日黎明，王就起來，急忙往獅子坑那裏去。", "ja": "こうして王は朝まだき起きて、ししの穴へ急いで行ったが、"}, "20": {"en": "When he came near to the den to Daniel, he cried with a troubled voice. The king spoke and said to Daniel, “Daniel, servant of the living God, is your God, whom you serve continually, able to deliver you from the lions?”", "zh": "臨近坑邊，哀聲呼叫但以理，對但以理說：「永生上帝的僕人但以理啊，你所常事奉的上帝能救你脫離獅子嗎？」", "ja": "ダニエルのいる穴に近づいたとき、悲しげな声をあげて呼ばわり、ダニエルに言った、「生ける神のしもべダニエルよ、あなたが常に仕えている神はあなたを救って、ししの害を免れさせることができたか」。"}, "21": {"en": "Then Daniel said to the king, “O king, live forever!", "zh": "但以理對王說：「願王萬歲！", "ja": "ダニエルは王に言った、「王よ、どうか、とこしえに生きながらえられますように。"}, "22": {"en": "My God has sent his angel, and has shut the lions’ mouths, and they have not hurt me, because innocence was found in me before him; and also before you, O king, I have done no harm.”", "zh": "我的上帝差遣使者，封住獅子的口，叫獅子不傷我；因我在上帝面前無辜，我在王面前也沒有行過虧損的事。」", "ja": "わたしの神はその使をおくって、ししの口を閉ざされたので、ししはわたしを害しませんでした。これはわたしに罪のないことが、神の前に認められたからです。王よ、わたしはあなたの前にも、何も悪い事をしなかったのです」。"}, "23": {"en": "Then the king was exceedingly glad, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no kind of harm was found on him, because he had trusted in his God.", "zh": "王就甚喜樂，吩咐人將但以理從坑裏繫上來。於是但以理從坑裏被繫上來，身上毫無傷損，因為信靠他的上帝。", "ja": "そこで王は大いに喜び、ダニエルを穴の中から出せと命じたので、ダニエルは穴の中から出されたが、その身になんの害をも受けていなかった。これは彼が自分の神を頼みとしていたからである。"}, "24": {"en": "The king commanded, and they brought those men who had accused Daniel, and they cast them into the den of lions—them, their children, and their wives; and the lions mauled them, and broke all their bones in pieces before they came to the bottom of the den.", "zh": "王下令，人就把那些控告但以理的人，連他們的妻子兒女都帶來，扔在獅子坑中。他們還沒有到坑底，獅子就抓住他們，咬碎他們的骨頭。", "ja": "王はまた命令を下して、ダニエルをあしざまに訴えた人々を引いてこさせ、彼らをその妻子と共に、ししの穴に投げ入れさせた。彼らが穴の底に達しないうちに、ししは彼らにとびかかって、その骨までもかみ砕いた。"}, "25": {"en": "Then King Darius wrote to all the peoples, nations, and languages who dwell in all the earth: “Peace be multiplied to you.", "zh": "那時，大流士王傳旨，曉諭住在全地各方、各國、各族的人說：「願你們大享平安！", "ja": "そこでダリヨス王は全世界に住む諸民、諸族、諸国語の者に詔を書きおくって言った、「どうか、あなたがたに平安が増すように。"}, "26": {"en": "“I make a decree that in all the dominion of my kingdom men tremble and fear before the God of Daniel. “For he is the living God, and steadfast forever. His kingdom is that which will not be destroyed. His dominion will be even to the end.", "zh": "現在我降旨曉諭我所統轄的全國人民，要在但以理的上帝面前，戰兢恐懼。 因為他是永遠長存的活上帝， 他的國永不敗壞； 他的權柄永存無極！", "ja": "わたしは命令を出す。わが国のすべての州の人は、皆ダニエルの神を、おののき恐れなければならない。彼は生ける神であって、とこしえに変ることなく、その国は滅びず、その主権は終りまで続く。"}, "27": {"en": "He delivers and rescues. He works signs and wonders in heaven and in earth, who has delivered Daniel from the power of the lions.”", "zh": "他護庇人，搭救人， 在天上地下施行神蹟奇事， 救了但以理脫離獅子的口。」", "ja": "彼は救を施し、助けをなし、天においても、地においても、しるしと奇跡とをおこない、ダニエルを救って、ししの力をのがれさせたかたである」。"}, "28": {"en": "So this Daniel prospered in the reign of Darius and in the reign of Cyrus the Persian.", "zh": "如此，這但以理，當大流士王在位的時候和波斯王塞魯士在位的時候，大享亨通。", "ja": "こうして、このダニエルはダリヨスの世と、ペルシャ人クロスの世において栄えた。"}}}, "7": {"verses": {"1": {"en": "In the first year of Belshazzar king of Babylon, Daniel had a dream and visions of his head while on his bed. Then he wrote the dream and told the sum of the matters.", "zh": "巴比倫王伯沙撒元年，但以理在床上做夢，見了腦中的異象，就記錄這夢，述說其中的大意。", "ja": "バビロンの王ベルシャザルの元年に、ダニエルは床にあって夢を見、また脳中に幻を得たので、彼はその夢をしるして、その事の大意を述べた。"}, "2": {"en": "Daniel spoke and said, “I saw in my vision by night, and, behold, the four winds of the sky broke out on the great sea.", "zh": "但以理說：", "ja": "ダニエルは述べて言った、「わたしは夜の幻のうちに見た。見よ、天の四方からの風が大海をかきたてると、"}, "3": {"en": "Four great animals came up from the sea, different from one another.", "zh": "我夜裏見異象，看見天的四風陡起，颳在大海之上。   有四個大獸從海中上來，形狀各有不同：", "ja": "四つの大きな獣が海からあがってきた。その形は、おのおの異なり、"}, "4": {"en": "“The first was like a lion, and had eagle’s wings. I watched until its wings were plucked, and it was lifted up from the earth and made to stand on two feet as a man. A man’s heart was given to it.", "zh": "頭一個像獅子，有鷹的翅膀；我正觀看的時候，獸的翅膀被拔去，獸從地上得立起來，用兩腳站立，像人一樣，又得了人心。", "ja": "第一のものは、ししのようで、わしの翼をもっていたが、わたしが見ていると、その翼は抜きとられ、また地から起されて、人のように二本の足で立たせられ、かつ人の心が与えられた。"}, "5": {"en": "“Behold, there was another animal, a second, like a bear. It was raised up on one side, and three ribs were in its mouth between its teeth. They said this to it: ‘Arise! Devour much flesh!’", "zh": "又有一獸如熊，就是第二獸，旁跨而坐，口齒內啣着三根肋骨。有吩咐這獸的說：「起來吞吃多肉。」", "ja": "見よ、第二の獣は熊のようであった。これはそのからだの一方をあげ、その口の歯の間に、三本の肋骨をくわえていたが、これに向かって『起きあがって、多くの肉を食らえ』と言う声があった。"}, "6": {"en": "“After this I saw, and behold, another, like a leopard, which had on its back four wings of a bird. The animal also had four heads; and dominion was given to it.", "zh": "此後我觀看，又有一獸如豹，背上有鳥的四個翅膀；這獸有四個頭，又得了權柄。", "ja": "その後わたしが見たのは、ひょうのような獣で、その背には鳥の翼が四つあった。またこの獣には四つの頭があり、主権が与えられた。"}, "7": {"en": "“After this I saw in the night visions, and, behold, there was a fourth animal, awesome, powerful, and exceedingly strong. It had great iron teeth. It devoured and broke in pieces, and stamped the residue with its feet. It was different from all the animals that were before it. It had ten horns.", "zh": "其後我在夜間的異象中觀看，見第四獸甚是可怕，極其強壯，大有力量，有大鐵牙，吞吃嚼碎，所剩下的用腳踐踏。這獸與前三獸大不相同，頭有十角。", "ja": "その後わたしが夜の幻のうちに見た第四の獣は、恐ろしい、ものすごい、非常に強いもので、大きな鉄の歯があり、食らい、かつ、かみ砕いて、その残りを足で踏みつけた。これは、その前に出たすべての獣と違って、十の角を持っていた。"}, "8": {"en": "“I considered the horns, and behold, there came up among them another horn, a little one, before which three of the first horns were plucked up by the roots; and behold, in this horn were eyes like the eyes of a man, and a mouth speaking arrogantly.", "zh": "我正觀看這些角，見其中又長起一個小角；先前的角中有三角在這角前，連根被牠拔出來。這角有眼，像人的眼，有口說誇大的話。", "ja": "わたしが、その角を注意して見ていると、その中に、また一つの小さい角が出てきたが、この小さい角のために、さきの角のうち三つがその根から抜け落ちた。見よ、この小さい角には、人の目のような目があり、また大きな事を語る口があった。"}, "9": {"en": "“I watched until thrones were placed, and one who was Ancient of Days sat. His clothing was white as snow, and the hair of his head like pure wool. His throne was fiery flames, and its wheels burning fire.", "zh": "我觀看， 見有寶座設立， 上頭坐着亙古常在者。 他的衣服潔白如雪， 頭髮如純淨的羊毛。 寶座乃火焰， 其輪乃烈火。", "ja": "わたしが見ていると、もろもろのみ座が設けられて、日の老いたる者が座しておられた。その衣は雪のように白く、頭の毛は混じりもののない羊の毛のようであった。そのみ座は火の炎であり、その車輪は燃える火であった。"}, "10": {"en": "A fiery stream issued and came out from before him. Thousands of thousands ministered to him. Ten thousand times ten thousand stood before him. The judgment was set. The books were opened.", "zh": "從他面前有火，像河發出； 事奉他的有千千， 在他面前侍立的有萬萬； 他坐着要行審判， 案卷都展開了。", "ja": "彼の前から、ひと筋の火の流れが出てきた。彼に仕える者は千々、彼の前にはべる者は万々、審判を行う者はその席に着き、かずかずの書き物が開かれた。"}, "11": {"en": "“I watched at that time because of the voice of the arrogant words which the horn spoke. I watched even until the animal was slain, and its body destroyed, and it was given to be burned with fire.", "zh": "那時我觀看，見那獸因小角說誇大話的聲音被殺，身體損壞，扔在火中焚燒。", "ja": "わたしは、その角の語る大いなる言葉の声がするので見ていたが、わたしが見ている間にその獣は殺され、そのからだはそこなわれて、燃える火に投げ入れられた。"}, "12": {"en": "As for the rest of the animals, their dominion was taken away; yet their lives were prolonged for a season and a time.", "zh": "其餘的獸，權柄都被奪去，生命卻仍存留，直到所定的時候和日期。", "ja": "その他の獣はその主権を奪われたが、その命は、時と季節の来るまで延ばされた。"}, "13": {"en": "“I saw in the night visions, and behold, there came with the clouds of the sky one like a son of man, and he came even to the Ancient of Days, and they brought him near before him.", "zh": "我在夜間的異象中觀看， 見有一位像人子的， 駕着天雲而來， 被領到亙古常在者面前，", "ja": "わたしはまた夜の幻のうちに見ていると、見よ、人の子のような者が、天の雲に乗ってきて、日の老いたる者のもとに来ると、その前に導かれた。"}, "14": {"en": "Dominion was given him, and glory, and a kingdom, that all the peoples, nations, and languages should serve him. His dominion is an everlasting dominion, which will not pass away, and his kingdom one that will not be destroyed.", "zh": "得了權柄、榮耀、國度， 使各方、各國、各族的人都事奉他。 他的權柄是永遠的，不能廢去； 他的國必不敗壞。", "ja": "彼に主権と光栄と国とを賜い、諸民、諸族、諸国語の者を彼に仕えさせた。その主権は永遠の主権であって、なくなることがなく、その国は滅びることがない。"}, "15": {"en": "“As for me, Daniel, my spirit was grieved within my body, and the visions of my head troubled me.", "zh": "至於我－但以理，我的靈在我裏面愁煩，我腦中的異象使我驚惶。", "ja": "そこで、われダニエル、わがうちなる霊は憂え、わが脳中の幻は、わたしを悩ましたので、"}, "16": {"en": "I came near to one of those who stood by, and asked him the truth concerning all this.", "zh": "我就近一位侍立者，問他這一切的真情。他就告訴我，將那事的講解給我說明：", "ja": "わたしは、そこに立っている者のひとりに近寄って、このすべての事の真意を尋ねた。するとその者は、わたしにこの事の解き明かしを告げ知らせた。"}, "17": {"en": "“So he told me, and made me know the interpretation of the things.   ‘These great animals, which are four, are four kings, who will arise out of the earth.", "zh": "這四個大獸就是四王將要在世上興起。", "ja": "『この四つの大きな獣は、地に起らんとする四人の王である。"}, "18": {"en": "But the saints of the Most High will receive the kingdom, and possess the kingdom forever, even forever and ever.’", "zh": "然而，至高者的聖民，必要得國享受，直到永永遠遠。", "ja": "しかしついには、いと高き者の聖徒が国を受け、永遠にその国を保って、世々かぎりなく続く』。"}, "19": {"en": "“Then I desired to know the truth concerning the fourth animal, which was different from all of them, exceedingly terrible, whose teeth were of iron, and its nails of bronze; which devoured, broke in pieces, and stamped the residue with its feet;", "zh": "那時我願知道第四獸的真情，牠為何與那三獸的真情大不相同，甚是可怕，有鐵牙銅爪，吞吃嚼碎，所剩下的用腳踐踏；", "ja": "そこでわたしは、さらに第四の獣の真意を知ろうとした。その獣は他の獣と異なって、はなはだ恐ろしく、その歯は鉄、そのつめは青銅であって、食らい、かつ、かみ砕いて、その残りを足で踏みつけた。"}, "20": {"en": "and concerning the ten horns that were on its head and the other horn which came up, and before which three fell, even that horn that had eyes and a mouth that spoke arrogantly, whose look was more stout than its fellows.", "zh": "頭有十角和那另長的一角，在這角前有三角被牠打落。這角有眼，有說誇大話的口，形狀強橫，過於牠的同類。", "ja": "この獣の頭には、十の角があったが、そのほかに一つの角が出てきたので、この角のために、三つの角が抜け落ちた。この角には目があり、また大きな事を語る口があって、その形は、その同類のものよりも大きく見えた。"}, "21": {"en": "I saw, and the same horn made war with the saints, and prevailed against them,", "zh": "我觀看，見這角與聖民爭戰，勝了他們。", "ja": "わたしが見ていると、この角は聖徒と戦って、彼らに勝ったが、"}, "22": {"en": "until the Ancient of Days came, and judgment was given to the saints of the Most High, and the time came that the saints possessed the kingdom.", "zh": "直到亙古常在者來給至高者的聖民伸冤，聖民得國的時候就到了。", "ja": "ついに日の老いたる者がきて、いと高き者の聖徒のために審判をおこなった。そしてその時がきて、この聖徒たちは国を受けた。"}, "23": {"en": "“So he said, ‘The fourth animal will be a fourth kingdom on earth, which will be different from all the kingdoms, and will devour the whole earth, and will tread it down and break it in pieces.", "zh": "那侍立者這樣說： 第四獸就是世上必有的第四國， 與一切國大不相同， 必吞吃全地， 並且踐踏嚼碎。", "ja": "彼はこう言った、『第四の獣は地上の第四の国である。これはすべての国と異なって、全世界を併合し、これを踏みつけ、かつ打ち砕く。"}, "24": {"en": "As for the ten horns, ten kings will arise out of this kingdom. Another will arise after them; and he will be different from the former, and he will put down three kings.", "zh": "至於那十角，就是從這國中必興起的十王， 後來又興起一王， 與先前的不同； 他必制伏三王。", "ja": "十の角はこの国から起る十人の王である。その後にまたひとりの王が起る。彼は先の者と異なり、かつ、その三人の王を倒す。"}, "25": {"en": "He will speak words against the Most High, and will wear out the saints of the Most High. He will plan to change the times and the law; and they will be given into his hand until a time and times and half a time.", "zh": "他必向至高者說誇大的話， 必折磨至高者的聖民， 必想改變節期和律法。 聖民必交付他手一載、二載、半載。", "ja": "彼は、いと高き者に敵して言葉を出し、かつ、いと高き者の聖徒を悩ます。彼はまた時と律法とを変えようと望む。聖徒はひと時と、ふた時と、半時の間、彼の手にわたされる。"}, "26": {"en": "“ ‘But the judgment will be set, and they will take away his dominion, to consume and to destroy it to the end.", "zh": "然而，審判者必坐着行審判； 他的權柄必被奪去， 毀壞，滅絕，一直到底。", "ja": "しかし審判が行われ、彼の主権は奪われて、永遠に滅び絶やされ、"}, "27": {"en": "The kingdom and the dominion, and the greatness of the kingdoms under the whole sky, will be given to the people of the saints of the Most High. His kingdom is an everlasting kingdom, and all dominions will serve and obey him.’", "zh": "國度、權柄，和天下諸國的大權 必賜給至高者的聖民。 他的國是永遠的； 一切掌權的都必事奉他，順從他。", "ja": "国と主権と全天下の国々の権威とは、いと高き者の聖徒たる民に与えられる。彼らの国は永遠の国であって、諸国の者はみな彼らに仕え、かつ従う』。"}, "28": {"en": "“Here is the end of the matter. As for me, Daniel, my thoughts troubled me greatly, and my face was changed in me; but I kept the matter in my heart.”", "zh": "那事至此完畢。至於我－但以理，心中甚是驚惶，臉色也改變了，卻將那事存記在心。", "ja": "その事はここで終った。われダニエルは、これを思いまわして、非常に悩み、顔色も変った。しかし、わたしはこの事を心に留めた」。"}}}, "8": {"verses": {"1": {"en": "In the third year of the reign of King Belshazzar, a vision appeared to me, even to me, Daniel, after that which appeared to me at the first.", "zh": "伯沙撒王在位第三年，有異象現與我－但以理，是在先前所見的異象之後。", "ja": "われダニエルは先に幻を見たが、後またベルシャザル王の治世の第三年に、一つの幻がわたしに示された。"}, "2": {"en": "I saw the vision. Now it was so, that when I saw, I was in the citadel of Susa, which is in the province of Elam. I saw in the vision, and I was by the river Ulai.", "zh": "我見了異象的時候，我以為在以攔省書珊城中；我見異象又如在烏萊河邊。", "ja": "その幻を見たのは、エラム州の首都スサにいた時であって、ウライ川のほとりにおいてであった。"}, "3": {"en": "Then I lifted up my eyes and saw, and behold, a ram which had two horns stood before the river. The two horns were high, but one was higher than the other, and the higher came up last.", "zh": "我舉目觀看，見有雙角的公綿羊站在河邊，兩角都高。這角高過那角，更高的是後長的。", "ja": "わたしが目をあげて見ると、川の岸に一匹の雄羊が立っていた。これに二つの角があって、その角は共に長かったが、一つの角は他の角よりも長かった。その長いのは後に伸びたのである。"}, "4": {"en": "I saw the ram pushing westward, northward, and southward. No animals could stand before him. There wasn’t any who could deliver out of his hand, but he did according to his will, and magnified himself.", "zh": "我見那公綿羊往西、往北、往南牴觸。獸在牠面前都站立不住，也沒有能救護脫離牠手的；但牠任意而行，自高自大。", "ja": "わたしが見ていると、その雄羊は、西、北、南にむかって突撃したが、これに当ることのできる獣は一匹もなく、またその手から救い出すことのできるものもなかった。これはその心のままにふるまい、みずから高ぶっていた。"}, "5": {"en": "As I was considering, behold, a male goat came from the west over the surface of the whole earth, and didn’t touch the ground. The goat had a notable horn between his eyes.", "zh": "我正思想的時候，見有一隻公山羊從西而來，遍行全地，腳不沾塵。這山羊兩眼當中有一非常的角。", "ja": "わたしがこれを考え、見ていると、一匹の雄やぎが、全地のおもてを飛びわたって西からきたが、その足は土を踏まなかった。このやぎには、目の間に著しい一つの角があった。"}, "6": {"en": "He came to the ram that had the two horns, which I saw standing before the river, and ran on him in the fury of his power.", "zh": "牠往我所看見、站在河邊有雙角的公綿羊那裏去，大發忿怒，向牠直闖。", "ja": "この者は、さきにわたしが川の岸に立っているのを見た、あの二つの角のある雄羊にむかってきて、激しく怒ってこれに走り寄った。"}, "7": {"en": "I saw him come close to the ram, and he was moved with anger against him, and struck the ram, and broke his two horns. There was no power in the ram to stand before him; but he cast him down to the ground and trampled on him. There was no one who could deliver the ram out of his hand.", "zh": "我見公山羊就近公綿羊，向牠發烈怒，牴觸牠，折斷牠的兩角。綿羊在牠面前站立不住；牠將綿羊觸倒在地，用腳踐踏，沒有能救綿羊脫離牠手的。", "ja": "わたしが見ていると、それが雄羊に近寄るや、これにむかって怒りを発し、雄羊を撃って、その二つの角を砕いた。雄羊には、これに当る力がなかったので、やぎは雄羊を地に打ち倒して踏みつけた。また、その雄羊を、やぎの力から救いうる者がなかった。"}, "8": {"en": "The male goat magnified himself exceedingly. When he was strong, the great horn was broken; and instead of it there came up four notable horns toward the four winds of the sky.", "zh": "這山羊極其自高自大，正強盛的時候，那大角折斷了，又在角根上向天的四方長出四個非常的角來。", "ja": "こうして、その雄やぎは、はなはだしく高ぶったが、その盛んになった時、あの大きな角が折れて、その代りに四つの著しい角が生じ、天の四方に向かった。"}, "9": {"en": "Out of one of them came out a little horn which grew exceedingly great—toward the south, and toward the east, and toward the glorious land.", "zh": "四角之中有一角長出一個小角，向南、向東、向榮美之地，漸漸成為強大。", "ja": "その角の一つから、一つの小さい角が出て、南に向かい、東に向かい、麗しい地に向かって、はなはだしく大きくなり、"}, "10": {"en": "It grew great, even to the army of the sky; and it cast down some of the army and of the stars to the ground and trampled on them.", "zh": "牠漸漸強大，高及天象，將些天象和星宿拋落在地，用腳踐踏。", "ja": "天の衆群に及ぶまでに大きくなり、星の衆群のうちの数個を地に投げ下して、これを踏みつけ、"}, "11": {"en": "Yes, it magnified itself, even to the prince of the army; and it took away from him the continual burnt offering, and the place of his sanctuary was cast down.", "zh": "並且牠自高自大，以為高及天象之君；除掉常獻給君的燔祭，毀壞君的聖所。", "ja": "またみずから高ぶって、その衆群の主に敵し、その常供の燔祭を取り除き、かつその聖所を倒した。"}, "12": {"en": "The army was given over to it together with the continual burnt offering through disobedience. It cast down truth to the ground, and it did its pleasure and prospered.", "zh": "因罪過的緣故，有軍旅和常獻的燔祭交付牠。牠將真理拋在地上，任意而行，無不順利。", "ja": "そしてその衆群は、罪によって、常供の燔祭と共に、これにわたされた。その角はまた真理を地に投げうち、ほしいままにふるまって、みずから栄えた。"}, "13": {"en": "Then I heard a holy one speaking; and another holy one said to that certain one who spoke, “How long will the vision about the continual burnt offering, and the disobedience that makes desolate, to give both the sanctuary and the army to be trodden under foot be?”", "zh": "我聽見有一位聖者說話，又有一位聖者問那說話的聖者說：「這除掉常獻的燔祭和施行毀壞的罪過，將聖所與軍旅踐踏的異象，要到幾時才應驗呢？」", "ja": "それから、わたしはひとりの聖者の語っているのを聞いた。またひとりの聖者があって、その語っている聖者にむかって言った、「常供の燔祭と、荒すことをなす罪と、聖所とその衆群がわたされて、足の下に踏みつけられることについて、幻にあらわれたことは、いつまでだろうか」と。"}, "14": {"en": "He said to me, “To two thousand and three hundred evenings and mornings. Then the sanctuary will be cleansed.”", "zh": "他對我說：「到二千三百日，聖所就必潔淨。」", "ja": "彼は言った、「二千三百の夕と朝の間である。そして聖所は清められてその正しい状態に復する」。"}, "15": {"en": "When I, even I Daniel, had seen the vision, I sought to understand it. Then behold, there stood before me someone with the appearance of a man.", "zh": "我－但以理見了這異象，願意明白其中的意思。忽有一位形狀像人的站在我面前。", "ja": "われダニエルはこの幻を見て、その意味を知ろうと求めていた時、見よ、人のように見える者が、わたしの前に立った。"}, "16": {"en": "I heard a man’s voice between the banks of the Ulai, which called and said, “Gabriel, make this man understand the vision.”", "zh": "我又聽見烏萊河兩岸中有人聲呼叫說：「加百列啊，要使此人明白這異象。」", "ja": "わたしはウライ川の両岸の間から人の声が出て、呼ばわるのを聞いた、「ガブリエルよ、この幻をその人に悟らせよ」。"}, "17": {"en": "So he came near where I stood; and when he came, I was frightened, and fell on my face; but he said to me, “Understand, son of man, for the vision belongs to the time of the end.”", "zh": "他便來到我所站的地方。他一來，我就驚慌俯伏在地；他對我說：「人子啊，你要明白，因為這是關乎末後的異象。」", "ja": "すると彼はわたしの立っている所にきた。彼がきたとき、わたしは恐れて、ひれ伏した。しかし、彼はわたしに言った、「人の子よ、悟りなさい。この幻は終りの時にかかわるものです」。"}, "18": {"en": "Now as he was speaking with me, I fell into a deep sleep with my face toward the ground; but he touched me and set me upright.", "zh": "他與我說話的時候，我面伏在地沉睡；他就摸我，扶我站起來，", "ja": "彼がわたしに語っていた時、わたしは地にひれ伏して、深い眠りに陥ったが、彼はわたしに手を触れ、わたしを立たせて、"}, "19": {"en": "He said, “Behold, I will make you know what will be in the latter time of the indignation, for it belongs to the appointed time of the end.", "zh": "說：「我要指示你惱怒臨完必有的事，因為這是關乎末後的定期。", "ja": "言った、「見よ、わたしは憤りの終りの時に起るべきことを、あなたに知らせよう。それは定められた終りの時にかかわるものであるから。"}, "20": {"en": "The ram which you saw, that had the two horns, they are the kings of Media and Persia.", "zh": "你所看見雙角的公綿羊，就是米底亞和波斯王。", "ja": "あなたが見た、あの二つの角のある雄羊は、メデアとペルシャの王です。"}, "21": {"en": "The rough male goat is the king of Greece. The great horn that is between his eyes is the first king.", "zh": "那公山羊就是希臘王；兩眼當中的大角就是頭一王。", "ja": "また、かの雄やぎはギリシヤの王です、その目の間の大きな角は、その第一の王です。"}, "22": {"en": "As for that which was broken, in the place where four stood up, four kingdoms will stand up out of the nation, but not with his power.", "zh": "至於那折斷了的角，在其根上又長出四角，這四角就是四國，必從這國裏興起來，只是權勢都不及他。", "ja": "またその角が折れて、その代りに四つの角が生じたのは、その民から四つの国が起るのです。しかし、第一の王のような勢力はない。"}, "23": {"en": "“In the latter time of their kingdom, when the transgressors have come to the full, a king of fierce face, and understanding riddles, will stand up.", "zh": "這四國末時，犯法的人罪惡滿盈，必有一王興起，面貌凶惡，能用雙關的詐語。", "ja": "彼らの国の終りの時になり、罪びとの罪が満ちるに及んで、ひとりの王が起るでしょう。その顔は猛悪で、彼はなぞを解き、"}, "24": {"en": "His power will be mighty, but not by his own power. He will destroy awesomely, and will prosper in what he does. He will destroy the mighty ones and the holy people.", "zh": "他的權柄必大，卻不是因自己的能力；他必行非常的毀滅，事情順利，任意而行；又必毀滅有能力的和聖民。", "ja": "その勢力は盛んであって、恐ろしい破壊をなし、そのなすところ成功して、有力な人々と、聖徒である民を滅ぼすでしょう。"}, "25": {"en": "Through his policy he will cause deceit to prosper in his hand. He will magnify himself in his heart, and he will destroy many in their security. He will also stand up against the prince of princes, but he will be broken without human hands.", "zh": "他用權術成就手中的詭計，心裏自高自大，在人坦然無備的時候，毀滅多人；又要站起來攻擊萬君之君，至終卻非因人手而滅亡。", "ja": "彼は悪知恵をもって、偽りをその手におこない遂げ、みずから心に高ぶり、不意に多くの人を打ち滅ぼし、また君の君たる者に敵するでしょう。しかし、ついに彼は人手によらずに滅ぼされるでしょう。"}, "26": {"en": "“The vision of the evenings and mornings which has been told is true; but seal up the vision, for it belongs to many days to come.”", "zh": "所說二千三百日的異象是真的，但你要將這異象封住，因為關乎後來許多的日子。」", "ja": "先に示された朝夕の幻は真実です。しかし、あなたはその幻を秘密にしておかなければならない。これは多くの日の後にかかわる事だから」。"}, "27": {"en": "I, Daniel, fainted, and was sick for some days. Then I rose up and did the king’s business. I wondered at the vision, but no one understood it.", "zh": "於是我－但以理昏迷不醒，病了數日，然後起來辦理王的事務。我因這異象驚奇，卻無人能明白其中的意思。", "ja": "われダニエルは疲れはてて、数日の間病みわずらったが、後起きて、王の事務を執った。しかし、わたしはこの幻の事を思って驚いた。またこれを悟ることができなかった。"}}}, "9": {"verses": {"1": {"en": "In the first year of Darius the son of Ahasuerus, of the offspring of the Medes, who was made king over the realm of the Chaldeans—", "zh": "米底亞族亞哈隨魯的兒子大流士立為迦勒底國的王元年，", "ja": "メデアびとアハシュエロスの子ダリヨスが、カルデヤびとの王となったその元年、"}, "2": {"en": "in the first year of his reign I, Daniel, understood by the books the number of the years about which the LORD’s word came to Jeremiah the prophet for the accomplishing of the desolations of Jerusalem, even seventy years.", "zh": "就是他在位第一年，我－但以理從書上得知耶和華的話臨到先知耶利米，論耶路撒冷荒涼的年數，七十年為滿。", "ja": "すなわちその治世の第一年に、われダニエルは主が預言者エレミヤに臨んで告げられたその言葉により、エルサレムの荒廃の終るまでに経ねばならぬ年の数は七十年であることを、文書によって悟った。"}, "3": {"en": "I set my face to the Lord God, to seek by prayer and petitions, with fasting and sackcloth and ashes.", "zh": "我便禁食，披麻蒙灰，定意向主上帝祈禱懇求。", "ja": "それでわたしは、わが顔を主なる神に向け、断食をなし、荒布を着、灰をかぶって祈り、かつ願い求めた。"}, "4": {"en": "I prayed to the LORD my God, and made confession, and said,", "zh": "我向耶和華－我的上帝祈禱、認罪，說：「主啊，大而可畏的上帝，向愛主、守主誡命的人守約施慈愛。", "ja": "すなわちわたしは、わが神、主に祈り、ざんげして言った、「ああ、大いなる恐るべき神、主、おのれを愛し、おのれの戒めを守る者のために契約を保ち、いつくしみを施される者よ、"}, "5": {"en": "“Oh, Lord, the great and dreadful God, who keeps covenant and loving kindness with those who love him and keep his commandments,   we have sinned, and have dealt perversely, and have done wickedly, and have rebelled, even turning aside from your precepts and from your ordinances.", "zh": "我們犯罪作孽，行惡叛逆，偏離你的誡命典章，", "ja": "われわれは罪を犯し、悪をおこない、よこしまなふるまいをなし、そむいて、あなたの戒めと、おきてを離れました。"}, "6": {"en": "We haven’t listened to your servants the prophets, who spoke in your name to our kings, our princes, and our fathers, and to all the people of the land.", "zh": "沒有聽從你僕人眾先知奉你名向我們君王、首領、列祖，和國中一切百姓所說的話。", "ja": "われわれはまた、あなたのしもべなる預言者たちが、あなたの名をもって、われわれの王たち、君たち、先祖たち、および国のすべての民に告げた言葉に聞き従いませんでした。"}, "7": {"en": "“Lord, righteousness belongs to you, but to us confusion of face, as it is today; to the men of Judah, and to the inhabitants of Jerusalem, and to all Israel, who are near and who are far off, through all the countries where you have driven them, because of their trespass that they have trespassed against you.", "zh": "主啊，你是公義的，我們是臉上蒙羞的；因我們猶大人和耶路撒冷的居民，並以色列眾人，或在近處，或在遠處，被你趕到各國的人，都得罪了你，正如今日一樣。", "ja": "主よ、正義はあなたのものですが、恥はわれわれに加えられて、今日のような有様です。すなわちユダの人々、エルサレムの住民および全イスラエルの者は、近き者も、遠き者もみな、あなたが追いやられたすべての国々で恥をこうむりました。これは彼らがあなたにそむいて犯した罪によるのです。"}, "8": {"en": "Lord, to us belongs confusion of face, to our kings, to our princes, and to our fathers, because we have sinned against you.", "zh": "主啊，我們和我們的君王、首領、列祖因得罪了你，就都臉上蒙羞。", "ja": "主よ、恥はわれわれのもの、われわれの王たち、君たちおよび先祖たちのものです。これはわれわれがあなたにむかって罪を犯したからです。"}, "9": {"en": "To the Lord our God belong mercies and forgiveness, for we have rebelled against him.", "zh": "主－我們的上帝是憐憫饒恕人的，我們卻違背了他，", "ja": "あわれみと、ゆるしはわれわれの神、主のものです。これはわれわれが彼にそむいたからです。"}, "10": {"en": "We haven’t obeyed the LORD our God’s voice, to walk in his laws, which he set before us by his servants the prophets.", "zh": "也沒有聽從耶和華－我們上帝的話，沒有遵行他藉僕人眾先知向我們所陳明的律法。", "ja": "またわれわれの神、主のみ声に聞き従わず、主がそのしもべ預言者たちによって、われわれの前に賜わった律法を行わなかったからです。"}, "11": {"en": "Yes, all Israel have transgressed your law, turning aside, that they should not obey your voice.", "zh": "以色列眾人都犯了你的律法，偏行，不聽從你的話；因此，在你僕人摩西律法上所寫的咒詛和誓言都傾在我們身上，因我們得罪了上帝。", "ja": "まことにイスラエルの人々は皆あなたの律法を犯し、離れ去って、あなたのみ声に聞き従わなかったので、神のしもべモーセの律法にしるされたのろいと誓いが、われわれの上に注ぎかかりました。これはわれわれが神にむかって罪を犯したからです。"}, "12": {"en": "“Therefore the curse and the oath written in the law of Moses the servant of God has been poured out on us, for we have sinned against him.   He has confirmed his words, which he spoke against us and against our judges who judged us, by bringing on us a great evil; for under the whole sky, such has not been done as has been done to Jerusalem.", "zh": "他使大災禍臨到我們，成就了警戒我們和審判我們官長的話；原來在普天之下未曾行過像在耶路撒冷所行的。", "ja": "すなわち神は大いなる災をわれわれの上にくだして、さきにわれわれと、われわれを治めたつかさたちにむかって告げられた言葉を実行されたのです。あのエルサレムに臨んだような事は、全天下にいまだかつてなかった事です。"}, "13": {"en": "As it is written in the law of Moses, all this evil has come on us. Yet we have not entreated the favor of the LORD our God, that we should turn from our iniquities and have discernment in your truth.", "zh": "這一切災禍臨到我們身上是照摩西律法上所寫的，我們卻沒有求耶和華－我們上帝的恩典，使我們回頭離開罪孽，明白你的真理。", "ja": "モーセの律法にしるされたように、この災はすべてわれわれに臨みましたが、なおわれわれの神、主の恵みを請い求めることをせず、その不義を離れて、あなたの真理を悟ることをもしませんでした。"}, "14": {"en": "Therefore the LORD has watched over the evil, and brought it on us; for the LORD our God is righteous in all his works which he does, and we have not obeyed his voice.", "zh": "所以耶和華留意使這災禍臨到我們身上，因為耶和華－我們的上帝在他所行的事上都是公義；我們並沒有聽從他的話。", "ja": "それゆえ、主はこれを心に留めて、災をわれわれに下されたのです。われわれの神、主は、何事をされるにも、正しくあらせられます。ところが、われわれはそのみ声に聞き従わなかったのです。"}, "15": {"en": "“Now, Lord our God, who has brought your people out of the land of Egypt with a mighty hand, and have gotten yourself renown, as it is today, we have sinned. We have done wickedly.", "zh": "主－我們的上帝啊，你曾用大能的手領你的子民出埃及地，使自己得了名，正如今日一樣。我們犯了罪，作了惡。", "ja": "われわれの神、主よ、あなたは強きみ手をもって、あなたの民をエジプトの地から導き出して、今日のように、み名をあげられました。われわれは罪を犯し、よこしまなふるまいをしました。"}, "16": {"en": "Lord, according to all your righteousness, please let your anger and your wrath be turned away from your city Jerusalem, your holy mountain; because for our sins and for the iniquities of our fathers, Jerusalem and your people have become a reproach to all who are around us.", "zh": "主啊，求你按你的大仁大義，使你的怒氣和忿怒轉離你的城耶路撒冷，就是你的聖山。耶路撒冷和你的子民，因我們的罪惡和我們列祖的罪孽被四圍的人羞辱。", "ja": "主よ、どうぞあなたが、これまで正しいみわざをなされたように、あなたの町エルサレム、あなたの聖なる山から、あなたの怒りと憤りとを取り去ってください。これはわれわれの罪と、われわれの先祖の不義のために、エルサレムと、あなたの民が、われわれの周囲の者の物笑いとなったからです。"}, "17": {"en": "“Now therefore, our God, listen to the prayer of your servant and to his petitions, and cause your face to shine on your sanctuary that is desolate, for the Lord’s sake.", "zh": "我們的上帝啊，現在求你垂聽僕人的祈禱懇求，為自己使臉光照你荒涼的聖所。", "ja": "それゆえ、われわれの神よ、しもべの祈と願いを聞いてください。主よ、あなたご自身のために、あの荒れたあなたの聖所に、あなたのみ顔を輝かせてください。"}, "18": {"en": "My God, turn your ear and hear. Open your eyes and see our desolations, and the city which is called by your name; for we do not present our petitions before you for our righteousness, but for your great mercies’ sake.", "zh": "我的上帝啊，求你側耳而聽，睜眼而看，眷顧我們荒涼之地和稱為你名下的城。我們在你面前懇求，原不是因自己的義，乃因你的大憐憫。", "ja": "わが神よ、耳を傾けて聞いてください。目を開いて、われわれの荒れたさまを見、み名をもってとなえられる町をごらんください。われわれがあなたの前に祈をささげるのは、われわれの義によるのではなく、ただあなたの大いなるあわれみによるのです。"}, "19": {"en": "Lord, hear. Lord, forgive. Lord, listen and do. Don’t defer, for your own sake, my God, because your city and your people are called by your name.”", "zh": "求主垂聽，求主赦免，求主應允而行，為你自己不要遲延。我的上帝啊，因這城和這民都是稱為你名下的。」", "ja": "主よ、聞いてください。主よ、ゆるしてください。主よ、み心に留めて、おこなってください。わが神よ、あなたご自身のために、これを延ばさないでください。あなたの町と、あなたの民は、み名をもってとなえられているからです」。"}, "20": {"en": "While I was speaking, praying, and confessing my sin and the sin of my people Israel, and presenting my supplication before the LORD my God for the holy mountain of my God—", "zh": "我說話，禱告，承認我的罪和本國之民以色列的罪，為我上帝的聖山，在耶和華－我上帝面前懇求。", "ja": "わたしがこう言って祈り、かつわが罪とわが民イスラエルの罪をざんげし、わが神の聖なる山のために、わが神、主の前に願いをしていたとき、"}, "21": {"en": "yes, while I was speaking in prayer—the man Gabriel, whom I had seen in the vision at the beginning, being caused to fly swiftly, touched me about the time of the evening offering.", "zh": "我正禱告的時候，先前在異象中所見的那位加百列，奉命迅速飛來，約在獻晚祭的時候，按手在我身上。", "ja": "すなわちわたしが祈の言葉を述べていたとき、わたしが初めに幻のうちに見た、かの人ガブリエルは、すみやかに飛んできて、夕の供え物をささげるころ、わたしに近づき、"}, "22": {"en": "He instructed me and talked with me, and said, “Daniel, I have now come to give you wisdom and understanding.", "zh": "他指教我說：「但以理啊，現在我出來要使你有智慧，有聰明。", "ja": "わたしに告げて言った、「ダニエルよ、わたしは今あなたに、知恵と悟りを与えるためにきました。"}, "23": {"en": "At the beginning of your petitions the commandment went out, and I have come to tell you, for you are greatly beloved. Therefore consider the matter and understand the vision.", "zh": "你初懇求的時候，就發出命令，我來告訴你，因你大蒙眷愛；所以你要思想明白這以下的事和異象。", "ja": "あなたが祈を始めたとき、み言葉が出たので、それをあなたに告げるためにきたのです。あなたは大いに愛せられている者です。ゆえに、このみ言葉を考えて、この幻を悟りなさい。"}, "24": {"en": "“Seventy weeks are decreed on your people and on your holy city, to finish disobedience, to make an end of sins, to make reconciliation for iniquity, to bring in everlasting righteousness, to seal up vision and prophecy, and to anoint the most holy.", "zh": "「為你本國之民和你聖城，已經定了七十個七。要止住罪過，除淨罪惡，贖盡罪孽，引進永義，封住異象和預言，並膏至聖者。", "ja": "あなたの民と、あなたの聖なる町については、七十週が定められています。これはとがを終らせ、罪に終りを告げ、不義をあがない、永遠の義をもたらし、幻と預言者を封じ、いと聖なる者に油を注ぐためです。"}, "25": {"en": "“Know therefore and discern that from the going out of the commandment to restore and build Jerusalem to the Anointed One, the prince, will be seven weeks and sixty-two weeks. It will be built again, with street and moat, even in troubled times.", "zh": "你當知道，當明白，從出令重新建造耶路撒冷，直到有受膏君的時候，必有七個七和六十二個七。正在艱難的時候，耶路撒冷城連街帶濠都必重新建造。", "ja": "それゆえ、エルサレムを建て直せという命令が出てから、メシヤなるひとりの君が来るまで、七週と六十二週あることを知り、かつ悟りなさい。その間に、しかも不安な時代に、エルサレムは広場と街路とをもって、建て直されるでしょう。"}, "26": {"en": "After the sixty-two weeks the Anointed One will be cut off, and will have nothing. The people of the prince who come will destroy the city and the sanctuary. Its end will be with a flood, and war will be even to the end. Desolations are determined.", "zh": "過了六十二個七，那受膏者必被剪除，一無所有；必有一王的民來毀滅這城和聖所，至終必如洪水沖沒。必有爭戰，一直到底，荒涼的事已經定了。", "ja": "その六十二週の後にメシヤは断たれるでしょう。ただし自分のためにではありません。またきたるべき君の民は、町と聖所とを滅ぼすでしょう。その終りは洪水のように臨むでしょう。そしてその終りまで戦争が続き、荒廃は定められています。"}, "27": {"en": "He will make a firm covenant with many for one week. In the middle of the week he will cause the sacrifice and the offering to cease. On the wing of abominations will come one who makes desolate; and even to the decreed full end, wrath will be poured out on the desolate.”", "zh": "一七之內，他必與許多人堅定盟約；一七之半，他必使祭祀與供獻止息。那行毀壞可憎的如飛而來，並且有忿怒傾在那行毀壞的身上，直到所定的結局。」", "ja": "彼は一週の間多くの者と、堅く契約を結ぶでしょう。そして彼はその週の半ばに、犠牲と供え物とを廃するでしょう。また荒す者が憎むべき者の翼に乗って来るでしょう。こうしてついにその定まった終りが、その荒す者の上に注がれるのです」。"}}}, "10": {"verses": {"1": {"en": "In the third year of Cyrus king of Persia a message was revealed to Daniel, whose name was called Belteshazzar; and the message was true, even a great warfare. He understood the message, and had understanding of the vision.", "zh": "波斯王塞魯士第三年，有事顯給稱為伯提沙撒的但以理。這事是真的，是指着大爭戰；但以理通達這事，明白這異象。", "ja": "ペルシャの王クロスの第三年に、ベルテシャザルと名づけられたダニエルに、一つの言葉が啓示されたが、その言葉は真実であり、大いなる戦いを意味するものであった。彼はその言葉に心を留め、その幻を悟った。"}, "2": {"en": "In those days I, Daniel, was mourning three whole weeks.", "zh": "當那時，我－但以理悲傷了三個七日。", "ja": "そのころ、われダニエルは三週の間、悲しんでいた。"}, "3": {"en": "I ate no pleasant food. No meat or wine came into my mouth. I didn’t anoint myself at all, until three whole weeks were fulfilled.", "zh": "美味我沒有吃，酒肉沒有入我的口，也沒有用油抹我的身，直到滿了三個七日。", "ja": "すなわち三週間の全く満ちるまでは、うまい物を食べず、肉と酒とを口にせず、また身に油を塗らなかった。"}, "4": {"en": "In the twenty-fourth day of the first month, as I was by the side of the great river, which is Hiddekel,", "zh": "正月二十四日，我在底格里斯大河邊，", "ja": "正月の二十四日に、わたしがチグリスという大川の岸に立っていたとき、"}, "5": {"en": "I lifted up my eyes and looked, and behold, there was a man clothed in linen, whose waist was adorned with pure gold of Uphaz.", "zh": "舉目觀看，見有一人身穿細麻衣，腰束烏法精金帶。", "ja": "目をあげて望み見ると、ひとりの人がいて、亜麻布の衣を着、ウパズの金の帯を腰にしめていた。"}, "6": {"en": "His body also was like beryl, and his face as the appearance of lightning, and his eyes as flaming torches. His arms and his feet were like burnished bronze. The voice of his words was like the voice of a multitude.", "zh": "他身體如水蒼玉，面貌如閃電，眼目如火把，手和腳如光明的銅，說話的聲音如大眾的聲音。", "ja": "そのからだは緑柱石のごとく、その顔は電光のごとく、その目は燃えるたいまつのごとく、その腕と足は、みがいた青銅のように輝き、その言葉の声は、群衆の声のようであった。"}, "7": {"en": "I, Daniel, alone saw the vision, for the men who were with me didn’t see the vision, but a great quaking fell on them, and they fled to hide themselves.", "zh": "這異象惟有我－但以理一人看見，同着我的人沒有看見。他們卻大大戰兢，逃跑隱藏，", "ja": "この幻を見た者は、われダニエルのみであって、わたしと共にいた人々は、この幻を見なかったが、彼らは大いにおののいて、逃げかくれた。"}, "8": {"en": "So I was left alone and saw this great vision. No strength remained in me; for my face grew deathly pale, and I retained no strength.", "zh": "只剩下我一人。我見了這大異象便渾身無力，面貌失色，毫無氣力。", "ja": "それでわたしひとり残って、この大いなる幻を見たので、力が抜け去り、わが顔の輝きは恐ろしく変って、全く力がなくなった。"}, "9": {"en": "Yet I heard the voice of his words. When I heard the voice of his words, then I fell into a deep sleep on my face, with my face toward the ground.", "zh": "我卻聽見他說話的聲音，一聽見就面伏在地沉睡了。", "ja": "わたしはその言葉の声を聞いたが、その言葉の声を聞いたとき、顔を伏せ、地にひれ伏して、深い眠りに陥った。"}, "10": {"en": "Behold, a hand touched me, which set me on my knees and on the palms of my hands.", "zh": "忽然，有一手按在我身上，使我用膝和手掌支持微起。", "ja": "見よ、一つの手があって、わたしに触れたので、わたしは震えながらひざまずき、手をつくと、"}, "11": {"en": "He said to me, “Daniel, you greatly beloved man, understand the words that I speak to you, and stand upright, for I have been sent to you, now.” When he had spoken this word to me, I stood trembling.", "zh": "他對我說：「大蒙眷愛的但以理啊，要明白我與你所說的話，只管站起來，因為我現在奉差遣來到你這裏。」他對我說這話，我便戰戰兢兢地立起來。", "ja": "彼はわたしに言った、「大いに愛せられる人ダニエルよ、わたしがあなたに告げる言葉に心を留め、立ちあがりなさい。わたしは今あなたのもとにつかわされたのです」。彼がこの言葉をわたしに告げているとき、わたしは震えながら立ちあがった。"}, "12": {"en": "Then he said to me, “Don’t be afraid, Daniel; for from the first day that you set your heart to understand, and to humble yourself before your God, your words were heard. I have come for your words’ sake.", "zh": "他就說：「但以理啊，不要懼怕！因為從你第一日專心求明白將來的事，又在你上帝面前刻苦己心，你的言語已蒙應允；我是因你的言語而來。", "ja": "すると彼はわたしに言った、「ダニエルよ、恐れるに及ばない。あなたが悟ろうと心をこめ、あなたの神の前に身を悩ましたその初めの日から、あなたの言葉は、すでに聞かれたので、わたしは、あなたの言葉のゆえにきたのです。"}, "13": {"en": "But the prince of the kingdom of Persia withstood me twenty-one days; but, behold, Michael, one of the chief princes, came to help me because I remained there with the kings of Persia.", "zh": "但波斯國的魔君攔阻我二十一日。忽然有大君中的一位米迦勒來幫助我，我就停留在波斯諸王那裏。", "ja": "ペルシャの国の君が、二十一日の間わたしの前に立ちふさがったが、天使の長のひとりであるミカエルがきて、わたしを助けたので、わたしは、彼をペルシャの国の君と共に、そこに残しておき、"}, "14": {"en": "Now I have come to make you understand what will happen to your people in the latter days, for the vision is yet for many days.”", "zh": "現在我來，要使你明白本國之民日後必遭遇的事，因為這異象關乎後來許多的日子。」", "ja": "末の日に、あなたの民に臨まんとする事を、あなたに悟らせるためにきたのです。この幻は、なおきたるべき日にかかわるものです」。"}, "15": {"en": "When he had spoken these words to me, I set my face toward the ground and was mute.", "zh": "他向我這樣說，我就臉面朝地，啞口無聲。", "ja": "彼がこれらの言葉を、わたしに述べていたとき、わたしは、地にひれ伏して黙っていたが、"}, "16": {"en": "Behold, one in the likeness of the sons of men touched my lips. Then I opened my mouth, and spoke and said to him who stood before me, “My lord, by reason of the vision my sorrows have overtaken me, and I retain no strength.", "zh": "不料，有一位像人的，摸我的嘴唇，我便開口向那站在我面前的說：「我主啊，因見這異象，我大大愁苦，毫無氣力。", "ja": "見よ、人の子のような者が、わたしのくちびるにさわったので、わたしは口を開き、わが前に立っている者に語って言った、「わが主よ、この幻によって、苦しみがわたしに臨み、全く力を失いました。"}, "17": {"en": "For how can the servant of this my lord talk with this my lord? For as for me, immediately there remained no strength in me. There was no breath left in me.”", "zh": "我主的僕人怎能與我主說話呢？我一見異象就渾身無力，毫無氣息。」", "ja": "わが主のしもべは、どうしてわが主と語ることができましょう。わたしは全く力を失い、息も止まるばかりです」。"}, "18": {"en": "Then one like the appearance of a man touched me again, and he strengthened me.", "zh": "有一位形狀像人的又摸我，使我有力量。", "ja": "人の形をした者は、再びわたしにさわり、わたしを力づけて、"}, "19": {"en": "He said, “Greatly beloved man, don’t be afraid. Peace be to you. Be strong. Yes, be strong.” When he spoke to me, I was strengthened, and said, “Let my lord speak, for you have strengthened me.”", "zh": "他說：「大蒙眷愛的人哪，不要懼怕，願你平安！你總要堅強。」他一向我說話，我便覺得有力量，說：「我主請說，因你使我有力量。」", "ja": "言った、「大いに愛せられる人よ、恐れるには及ばない。安心しなさい。心を強くし、勇気を出しなさい」。彼がこう言ったとき、わたしは力づいて言った、「わが主よ、語ってください。あなたは、わたしに力をつけてくださったから」。"}, "20": {"en": "Then he said, “Do you know why I have come to you? Now I will return to fight with the prince of Persia. When I go out, behold, the prince of Greece will come.", "zh": "他就說：「你知道我為何來見你嗎？現在我要回去與波斯的魔君爭戰，我去後，希臘的魔君必來。", "ja": "そこで彼は言った、「あなたは、わたしがなんのためにきたかを知っていますか。わたしは、今帰っていって、ペルシャの君と戦おうとしているのです。彼との戦いがすむと、ギリシヤの君があらわれるでしょう。"}, "21": {"en": "But I will tell you that which is inscribed in the writing of truth. There is no one who holds with me against these but Michael your prince.", "zh": "但我要將那錄在真確書上的事告訴你。除了你們的大君米迦勒之外，沒有幫助我抵擋這兩魔君的。」", "ja": "しかしわたしは、まず真理の書にしるされている事を、あなたに告げよう。わたしを助けて、彼らと戦う者は、あなたがたの君ミカエルのほかにはありません。"}}}, "11": {"verses": {"1": {"en": "“As for me, in the first year of Darius the Mede, I stood up to confirm and strengthen him.", "zh": "又說：「當米底亞王大流士元年，我曾起來扶助米迦勒，使他堅強。」", "ja": "わたしはまたメデアびとダリヨスの元年に立って彼を強め、彼を力づけたことがあります。"}, "2": {"en": "“Now I will show you the truth. Behold, three more kings will stand up in Persia. The fourth will be far richer than all of them. When he has grown strong through his riches, he will stir up all against the realm of Greece.", "zh": "現在我將真事指示你：", "ja": "わたしは今あなたに真理を示そう。見よ、ペルシャになお三人の王が起るでしょう。その第四の者は、他のすべての者にまさって富み、その富によって強くなったとき、彼はすべてのものを動員して、ギリシヤの国を攻めます。"}, "3": {"en": "A mighty king will stand up, who will rule with great dominion, and do according to his will.", "zh": "「波斯還有三王興起，第四王必富足遠勝諸王。他因富足成為強盛，就必激動大眾攻擊希臘國。   必有一個勇敢的王興起，執掌大權，隨意而行。", "ja": "またひとりの勇ましい王が起り、大いなる権力をもって世を治め、その意のままに事をなすでしょう。"}, "4": {"en": "When he stands up, his kingdom will be broken and will be divided toward the four winds of the sky, but not to his posterity, nor according to his dominion with which he ruled; for his kingdom will be plucked up, even for others besides these.", "zh": "他興起的時候，他的國必破裂，向天的四方分開，卻不歸他的後裔，治國的權勢也都不及他；因為他的國必被拔出，歸與他後裔之外的人。", "ja": "彼が強くなった時、その国は破られ、天の四方に分かたれます。それは彼の子孫に帰せず、また彼が治めたほどの権力もなく、彼の国は抜き取られて、これら以外の者どもに帰するでしょう。"}, "5": {"en": "“The king of the south will be strong. One of his princes will become stronger than him, and have dominion. His dominion will be a great dominion.", "zh": "「南方的王必強盛，他將帥中必有一個比他更強盛，執掌權柄，他的權柄甚大。", "ja": "南の王は強くなります。しかしその将軍のひとりが、彼にまさって強くなり、権力をふるいます。その権力は、大いなる権力です。"}, "6": {"en": "At the end of years they will join themselves together; and the daughter of the king of the south will come to the king of the north to make an agreement, but she will not retain the strength of her arm. He will also not stand, nor will his arm; but she will be given up, with those who brought her, and he who became the father of her, and he who strengthened her in those times.", "zh": "過些年後，他們必互相連合，南方王的女兒必就了北方王來立約；但這女子幫助之力存立不住，王和他所倚靠之力也不能存立。這女子和引導她來的，並生她的，以及當時扶助她的，都必交與死地。", "ja": "年を経て後、彼らは縁組をなし、南の王の娘が、北の王にきて、和親をはかります。しかしその女は、その腕の力を保つことができず、またその王も、その子も立つことができません。その女と、その従者と、その子およびその女を獲た者とは、わたされるでしょう。"}, "7": {"en": "“But out of a shoot from her roots one will stand up in his place, who will come to the army and will enter into the fortress of the king of the north, and will deal against them and will prevail.", "zh": "但這女子的本家必另生一子繼續王位，他必率領軍隊進入北方王的保障，攻擊他們，而且得勝；", "ja": "そのころ、この女の根から、一つの芽が起って彼に代り、北の王の軍勢にむかってきて、その城に討ち入り、これを攻めて勝つでしょう。"}, "8": {"en": "He will also carry their gods with their molten images, and with their goodly vessels of silver and of gold, captive into Egypt. He will refrain some years from the king of the north.", "zh": "並將他們的神像和鑄成的偶像，與金銀的寶器掠到埃及去。數年之內，他不去攻擊北方的王。", "ja": "彼はまた彼らの神々、鋳像および金銀の貴重な器物を、エジプトに携え去り、そして数年の間、北の王を討つことを控えます。"}, "9": {"en": "He will come into the realm of the king of the south, but he will return into his own land.", "zh": "北方的王必入南方王的國，卻要仍回本地。", "ja": "その後、北の王は、南の王の国に討ち入るが、自分の国に帰るでしょう。"}, "10": {"en": "His sons will wage war, and will assemble a multitude of great forces which will come on, and overflow, and pass through. They will return and wage war, even to his fortress.", "zh": "「北方王的二子必動干戈，招聚許多軍兵。這軍兵前去，如洪水氾濫，又必再去爭戰，直到南方王的保障。", "ja": "その子らはまた憤激して、あまたの大軍を集め、進んで行って、みなぎりあふれ、通り過ぎるが、また行って、その城にまで攻め寄せるでしょう。"}, "11": {"en": "“The king of the south will be moved with anger and will come out and fight with him, even with the king of the north. He will send out a great multitude, and the multitude will be given into his hand.", "zh": "南方王必發烈怒，出來與北方王爭戰，擺列大軍；北方王的軍兵必交付他手。", "ja": "そこで南の王は、大いに怒り、出てきて北の王と戦います。彼は大軍を起すけれども、その軍は相手の手にわたされるでしょう。"}, "12": {"en": "The multitude will be carried off, and his heart will be exalted. He will cast down tens of thousands, but he won’t prevail.", "zh": "他的眾軍高傲，他的心也必自高；他雖使數萬人仆倒，卻不得常勝。", "ja": "彼がその軍を打ち破ったとき、その心は高ぶり、数万人を倒します。しかし、勝つことはありません。"}, "13": {"en": "The king of the north will return, and will send out a multitude greater than the former. He will come on at the end of the times, even of years, with a great army and with abundant supplies.", "zh": "「北方王必回來擺列大軍，比先前的更多。滿了所定的年數，他必率領大軍，帶極多的軍裝來。", "ja": "それは北の王がまた初めよりも大いなる軍を起し、数年の後、大いなる軍勢と多くの軍需品とをもって、攻めて来るからです。"}, "14": {"en": "“In those times many will stand up against the king of the south. Also the children of the violent among your people will lift themselves up to establish the vision, but they will fall.", "zh": "那時，必有許多人起來攻擊南方王，並且你本國的強暴人必興起，要應驗那異象，他們卻要敗亡。", "ja": "そのころ多くの者が起って、南の王に敵します。またあなたの民のうちのあらくれ者が、みずから高ぶって事をなし、幻を成就しようとするが失敗するでしょう。"}, "15": {"en": "So the king of the north will come and cast up a mound, and take a well-fortified city. The forces of the south won’t stand, neither will his select troops, neither will there be any strength to stand.", "zh": "北方王必來築壘攻取堅固城；南方的軍兵必站立不住，就是選擇的精兵也無力站住。", "ja": "こうして北の王がきて、塁を築き、堅固な町を取るが、南の王の力は、これに立ち向かうことができず、またそのえり抜きの民も、これに立ち向かう力がありません。"}, "16": {"en": "But he who comes against him will do according to his own will, and no one will stand before him. He will stand in the glorious land, and destruction will be in his hand.", "zh": "來攻擊他的，必任意而行，無人在北方王面前站立得住。他必站在那榮美之地，用手施行毀滅。", "ja": "これに攻めて来る者は、その心のままに事をなし、その前に立ち向かうことのできる者はなく、彼は麗しい地に立ち、その地は全く彼のために荒されます。"}, "17": {"en": "He will set his face to come with the strength of his whole kingdom, and with him equitable conditions. He will perform them. He will give him the daughter of women, to destroy the kingdom, but she will not stand, and won’t be for him.", "zh": "「他必定意用全國之力而來，立公正的約，照約而行，將自己的女兒給南方王為妻，想要敗壞他，這計卻不得成就，與自己毫無益處。", "ja": "彼は全国の力をもって討ち入ろうと、その顔を向けるが、相手と仲直りをし、その娘を与えて、その国を取ろうとします。しかし、その事は成らず、また彼の利益にはならないでしょう。"}, "18": {"en": "After this he will turn his face to the islands, and will take many, but a prince will cause the reproach offered by him to cease. Yes, moreover, he will cause his reproach to turn on him.", "zh": "其後他必轉回奪取了許多海島。但有一大帥，除掉他令人受的羞辱，並且使這羞辱歸他本身。", "ja": "その後、彼は顔を海沿いの国々に向けて、その多くのものを取ります。しかし、ひとりの大将があって、彼が与えた恥辱をそそぎ、その恥辱を彼の上に返します。"}, "19": {"en": "Then he will turn his face toward the fortresses of his own land; but he will stumble and fall, and won’t be found.", "zh": "他就必轉向本地的保障，卻要絆跌仆倒，歸於無有。", "ja": "こうして彼は、その顔を自分の国の要害に向けるが、彼はつまずき倒れて消えうせるでしょう。"}, "20": {"en": "“Then one who will cause a tax collector to pass through the kingdom to maintain its glory will stand up in his place; but within few days he shall be destroyed, not in anger, and not in battle.", "zh": "「那時，必有一人興起接續他為王，使橫征暴斂的人通行國中的榮美地。這王不多日就必滅亡，卻不因忿怒，也不因爭戰。」", "ja": "彼に代って起る者は、栄光の国に人をつかわして、租税を取り立てさせるでしょう。しかし彼は、怒りにも戦いにもよらず、数日のうちに滅ぼされます。"}, "21": {"en": "“In his place a contemptible person will stand up, to whom they had not given the honor of the kingdom; but he will come in time of security, and will obtain the kingdom by flatteries.", "zh": "「必有一個卑鄙的人興起接續為王，人未曾將國的尊榮給他，他卻趁人坦然無備的時候，用諂媚的話得國。", "ja": "彼に代って起る者は、卑しむべき者であって、彼には、王の尊厳が与えられず、彼は不意にきて、巧言をもって国を獲るでしょう。"}, "22": {"en": "The overwhelming forces will be overwhelmed from before him, and will be broken. Yes, also the prince of the covenant.", "zh": "必有無數的軍兵勢如洪水，在他面前沖沒敗壞；同盟的君也必如此。", "ja": "洪水のような軍勢は、彼の前に押し流されて敗られ、契約の君たる者もまた敗られるでしょう。"}, "23": {"en": "After the treaty made with him he will work deceitfully; for he will come up and will become strong with few people.", "zh": "與那君結盟之後，他必行詭詐，因為他必上來以微小的軍成為強盛。", "ja": "彼は、これと同盟を結んで後、偽りのおこないをなし、わずかな民をもって強くなり、"}, "24": {"en": "In time of security he will come even on the fattest places of the province. He will do that which his fathers have not done, nor his fathers’ fathers. He will scatter among them prey, plunder, and wealth. Yes, he will devise his plans against the strongholds, but only for a time.", "zh": "趁人坦然無備的時候，他必來到國中極肥美之地，行他列祖和他列祖之祖所未曾行的，將擄物、掠物，和財寶散給眾人，又要設計攻打保障，然而這都是暫時的。", "ja": "不意にその州の最も肥えた所に攻め入り、その父も、その父の父もしなかった事をおこない、その奪った物、かすめた物および財宝を、人々の中に散らすでしょう。彼はまた計略をめぐらして、堅固な城を攻めるが、ただし、それは時の至るまでです。"}, "25": {"en": "“He will stir up his power and his courage against the king of the south with a great army; and the king of the south will wage war in battle with an exceedingly great and mighty army, but he won’t stand; for they will devise plans against him.", "zh": "「他必奮勇向前，率領大軍攻擊南方王；南方王也必以極大極強的軍兵與他爭戰，卻站立不住，因為有人設計謀害南方王。", "ja": "彼はその勢力と勇気とを奮い起し、大軍を率いて南の王を攻めます。南の王もまたみずから奮い、はなはだ大いなる強力な軍勢をもって戦います。しかし、彼に対して、陰謀をめぐらす者があるので、これに立ち向かうことができません。"}, "26": {"en": "Yes, those who eat of his delicacies will destroy him, and his army will be swept away. Many will fall down slain.", "zh": "吃王膳的，必敗壞他；他的軍隊必被沖沒，而且被殺的甚多。", "ja": "すなわち彼の食物を食べる者たちが、彼を滅ぼします。そして、その軍勢は押し流されて、多くの者が倒れ死ぬでしょう。"}, "27": {"en": "As for both these kings, their hearts will be to do evil, and they will speak lies at one table; but it won’t prosper, for the end will still be at the appointed time.", "zh": "至於這二王，他們心懷惡計，同席說謊，計謀卻不成就；因為到了定期，事就了結。", "ja": "このふたりの王は、害を与えようと心にはかり、ひとつ食卓に共に食して、偽りを語るが、それは成功しません。終りはなお定まった時の来るまでこないからです。"}, "28": {"en": "Then he will return into his land with great wealth. His heart will be against the holy covenant. He will take action, and return to his own land.", "zh": "北方王必帶許多財寶回往本國，他的心反對聖約，任意而行，回到本地。", "ja": "彼は大いなる財宝をもって、自分の国に帰るでしょう。しかし、彼の心は聖なる契約にそむき、ほしいままに事をなして、自分の国に帰ります。"}, "29": {"en": "“He will return at the appointed time and come into the south; but it won’t be in the latter time as it was in the former.", "zh": "「到了定期，他必返回，來到南方。後一次卻不如前一次，", "ja": "定まった時になって、彼はまた南に討ち入ります。しかし、この時は前の時のようではありません。"}, "30": {"en": "For ships of Kittim will come against him. Therefore he will be grieved, and will return, and have indignation against the holy covenant, and will take action. He will even return, and have regard to those who forsake the holy covenant.", "zh": "因為基提戰船必來攻擊他，他就喪膽而回，又要惱恨聖約，任意而行；他必回來聯絡背棄聖約的人。", "ja": "それはキッテムの船が、彼に立ち向かって来るので、彼は脅かされて帰り、聖なる契約に対して憤り、事を行うでしょう。彼は帰っていって、聖なる契約を捨てる者を顧み用いるでしょう。"}, "31": {"en": "“Forces from him will profane the sanctuary, even the fortress, and will take away the continual burnt offering. Then they will set up the abomination that makes desolate.", "zh": "他必興兵，這兵必褻瀆聖地，就是保障，除掉常獻的燔祭，設立那行毀壞可憎的。", "ja": "彼から軍勢が起って、神殿と城郭を汚し、常供の燔祭を取り除き、荒す憎むべきものを立てるでしょう。"}, "32": {"en": "He will corrupt those who do wickedly against the covenant by flatteries; but the people who know their God will be strong and take action.", "zh": "作惡違背聖約的人，他必用巧言勾引；惟獨認識上帝的子民必剛強行事。", "ja": "彼は契約を破る者どもを、巧言をもってそそのかし、そむかせるが、自分の神を知る民は、堅く立って事を行います。"}, "33": {"en": "“Those who are wise among the people will instruct many; yet they will fall by the sword and by flame, by captivity and by plunder, many days.", "zh": "民間的智慧人必訓誨多人；然而他們多日必倒在刀下，或被火燒，或被擄掠搶奪。", "ja": "民のうちの賢い人々は、多くの人を悟りに至らせます。それでも、彼らはしばらくの間、やいばにかかり、火に焼かれ、捕われ、かすめられなどして倒れます。"}, "34": {"en": "Now when they fall, they will be helped with a little help; but many will join themselves to them with flatteries.", "zh": "他們仆倒的時候，稍得扶助，卻有許多人用諂媚的話親近他們。", "ja": "その倒れるとき、彼らは少しの助けを獲ます。また多くの人が、巧言をもって彼らにくみするでしょう。"}, "35": {"en": "Some of those who are wise will fall—to refine them, and to purify, and to make them white, even to the time of the end, because it is yet for the time appointed.", "zh": "智慧人中有些仆倒的，為要熬煉其餘的人，使他們清淨潔白，直到末了；因為到了定期，事就了結。", "ja": "また賢い者のうちのある者は、終りの時まで、自分を練り、清め、白くするために倒れるでしょう。終りはなお定まった時の来るまでこないからです。"}, "36": {"en": "“The king will do according to his will. He will exalt himself and magnify himself above every god, and will speak marvelous things against the God of gods. He will prosper until the indignation is accomplished, for that which is determined will be done.", "zh": "「王必任意而行，自高自大，超過所有的神，又用奇異的話攻擊萬神之神。他必行事亨通，直到主的忿怒完畢，因為所定的事必然成就。", "ja": "この王は、その心のままに事をおこない、すべての神を越えて、自分を高くし、自分を大いにし、神々の神たる者にむかって、驚くべき事を語り、憤りのやむ時まで栄えるでしょう。これは定められた事が成就するからです。"}, "37": {"en": "He won’t regard the gods of his fathers, or the desire of women, or regard any god; for he will magnify himself above all.", "zh": "他必不顧他列祖的神，也不顧婦女所羨慕的神，無論何神他都不顧；因為他必自大，高過一切。", "ja": "彼はその先祖の神々を顧みず、また婦人の好む者も、いかなる神をも顧みないでしょう。彼はすべてにまさって、自分を大いなる者とするからです。"}, "38": {"en": "But in their place, he will honor the god of fortresses. He will honor a god whom his fathers didn’t know with gold, silver, and with precious stones and pleasant things.", "zh": "他倒要敬拜保障的神，用金、銀、寶石和可愛之物敬奉他列祖所不認識的神。", "ja": "彼はこれらの者の代りに、要害の神をあがめ、金、銀、宝石、および宝物をもって、その先祖たちの知らなかった神をあがめ、"}, "39": {"en": "He will deal with the strongest fortresses by the help of a foreign god. He will increase with glory whoever acknowledges him. He will cause them to rule over many, and will divide the land for a price.", "zh": "他必靠外邦神的幫助，攻破最堅固的保障。凡承認他的，他必將榮耀加給他們，使他們管轄許多人，又為賄賂分地與他們。", "ja": "異邦の神の助けによって、最も強固な城にむかって、事をなすでしょう。そして彼を認める者には、栄誉を増し与え、これに多くの人を治めさせ、賞与として土地を分け与えるでしょう。"}, "40": {"en": "“At the time of the end the king of the south will contend with him; and the king of the north will come against him like a whirlwind, with chariots, with horsemen, and with many ships. He will enter into the countries, and will overflow and pass through.", "zh": "「到末了，南方王要與他交戰。北方王必用戰車、馬兵，和許多戰船，勢如暴風來攻擊他，也必進入列國，如洪水氾濫。", "ja": "終りの時になって、南の王は彼と戦います。北の王は、戦車と騎兵と、多くの船をもって、つむじ風のように彼を攻め、国々にはいっていって、みなぎりあふれ、通り過ぎるでしょう。"}, "41": {"en": "He will enter also into the glorious land, and many countries will be overthrown; but these will be delivered out of his hand: Edom, Moab, and the chief of the children of Ammon.", "zh": "又必進入那榮美之地，有許多國就被傾覆，但以東人、摩押人，和一大半亞捫人必脫離他的手。", "ja": "彼はまた麗しい国にはいります。また彼によって、多くの者が滅ぼされます。しかし、エドム、モアブ、アンモンびとらのうちのおもな者は、彼の手から救われましょう。"}, "42": {"en": "He will also stretch out his hand on the countries. The land of Egypt won’t escape.", "zh": "他必伸手攻擊列國；埃及地也不得脫離。", "ja": "彼は国々にその手を伸ばし、エジプトの地も免れません。"}, "43": {"en": "But he will have power over the treasures of gold and of silver, and over all the precious things of Egypt. The Libyans and the Ethiopians will follow his steps.", "zh": "他必把持埃及的金銀財寶和各樣的寶物。利比亞人和古實人都必跟從他。", "ja": "彼は金銀の財宝と、エジプトのすべての宝物を支配し、リビヤびと、エチオピヤびとは、彼のあとに従います。"}, "44": {"en": "But news out of the east and out of the north will trouble him; and he will go out with great fury to destroy and utterly to sweep away many.", "zh": "但從東方和北方必有消息擾亂他，他就大發烈怒出去，要將多人殺滅淨盡。", "ja": "しかし東と北からの知らせが彼を驚かし、彼は多くの人を滅ぼし絶やそうと、大いなる怒りをもって出て行きます。"}, "45": {"en": "He will plant the tents of his palace between the sea and the glorious holy mountain; yet he will come to his end, and no one will help him.", "zh": "他必在海和榮美的聖山中間設立他如宮殿的帳幕；然而到了他的結局，必無人能幫助他。」", "ja": "彼は海と麗しい聖山との間に、天幕の宮殿を設けるでしょう。しかし、彼はついにその終りにいたり、彼を助ける者はないでしょう。"}}}, "12": {"verses": {"1": {"en": "“At that time Michael will stand up, the great prince who stands for the children of your people; and there will be a time of trouble, such as never was since there was a nation even to that same time. At that time your people will be delivered, everyone who is found written in the book.", "zh": "「那時，保佑你本國之民的天使長米迦勒必站起來，並且有大艱難，從有國以來直到此時，沒有這樣的。你本國的民中，凡名錄在冊上的，必得拯救。", "ja": "その時あなたの民を守っている大いなる君ミカエルが立ちあがります。また国が始まってから、その時にいたるまで、かつてなかったほどの悩みの時があるでしょう。しかし、その時あなたの民は救われます。すなわちあの書に名をしるされた者は皆救われます。"}, "2": {"en": "Many of those who sleep in the dust of the earth will awake, some to everlasting life, and some to shame and everlasting contempt.", "zh": "睡在塵埃中的，必有多人復醒。其中有得永生的，有受羞辱永遠被憎惡的。", "ja": "また地のちりの中に眠っている者のうち、多くの者は目をさますでしょう。そのうち永遠の生命にいたる者もあり、また恥と、限りなき恥辱をうける者もあるでしょう。"}, "3": {"en": "Those who are wise will shine as the brightness of the expanse. Those who turn many to righteousness will shine as the stars forever and ever.", "zh": "智慧人必發光如同天上的光；那使多人歸義的，必發光如星，直到永永遠遠。", "ja": "賢い者は、大空の輝きのように輝き、また多くの人を義に導く者は、星のようになって永遠にいたるでしょう。"}, "4": {"en": "But you, Daniel, shut up the words and seal the book, even to the time of the end. Many will run back and forth, and knowledge will be increased.”", "zh": "但以理啊，你要隱藏這話，封閉這書，直到末時。必有多人來往奔跑，知識就必增長。」", "ja": "ダニエルよ、あなたは終りの時までこの言葉を秘し、この書を封じておきなさい。多くの者は、あちこちと探り調べ、そして知識が増すでしょう」。"}, "5": {"en": "Then I, Daniel, looked, and behold, two others stood, one on the river bank on this side, and the other on the river bank on that side.", "zh": "我－但以理觀看，見另有兩個人站立：一個在河這邊，一個在河那邊。", "ja": "そこで、われダニエルが見ていると、ほかにまたふたりの者があって、ひとりは川のこなたの岸に、ひとりは川のかなたの岸に立っていた。"}, "6": {"en": "One said to the man clothed in linen, who was above the waters of the river, “How long will it be to the end of these wonders?”", "zh": "有一個問那站在河水以上、穿細麻衣的說：「這奇異的事到幾時才應驗呢？」", "ja": "わたしは、かの亜麻布を着て川の水の上にいる人にむかって言った、「この異常なできごとは、いつになって終るでしょうか」と。"}, "7": {"en": "I heard the man clothed in linen, who was above the waters of the river, when he held up his right hand and his left hand to heaven, and swore by him who lives forever that it will be for a time, times, and a half; and when they have finished breaking in pieces the power of the holy people, all these things will be finished.", "zh": "我聽見那站在河水以上、穿細麻衣的，向天舉起左右手，指着活到永遠的主起誓說：「要到一載、二載、半載，打破聖民權力的時候，這一切事就都應驗了。」", "ja": "かの亜麻布を着て、川の水の上にいた人が、天に向かって、その右の手と左の手をあげ、永遠に生ける者をさして誓い、それは、ひと時とふた時と半時である。聖なる民を打ち砕く力が消え去る時に、これらの事はみな成就するだろうと言うのを、わたしは聞いた。"}, "8": {"en": "I heard, but I didn’t understand. Then I said, “My lord, what will be the outcome of these things?”", "zh": "我聽見這話，卻不明白，就說：「我主啊，這些事的結局是怎樣呢？」", "ja": "わたしはこれを聞いたけれども悟れなかった。わたしは言った、「わが主よ、これらの事の結末はどんなでしょうか」。"}, "9": {"en": "He said, “Go your way, Daniel; for the words are shut up and sealed until the time of the end.", "zh": "他說：「但以理啊，你只管去；因為這話已經隱藏封閉，直到末時。", "ja": "彼は言った、「ダニエルよ、あなたの道を行きなさい。この言葉は終りの時まで秘し、かつ封じておかれます。"}, "10": {"en": "Many will purify themselves, and make themselves white, and be refined, but the wicked will do wickedly; and none of the wicked will understand, but those who are wise will understand.", "zh": "必有許多人使自己清淨潔白，且被熬煉；但惡人仍必行惡，一切惡人都不明白，惟獨智慧人能明白。", "ja": "多くの者は、自分を清め、自分を白くし、かつ練られるでしょう。しかし、悪い者は悪い事をおこない、ひとりも悟ることはないが、賢い者は悟るでしょう。"}, "11": {"en": "“From the time that the continual burnt offering is taken away and the abomination that makes desolate set up, there will be one thousand two hundred ninety days.", "zh": "從除掉常獻的燔祭，並設立那行毀壞可憎之物的時候，必有一千二百九十日。", "ja": "常供の燔祭が取り除かれ、荒す憎むべきものが立てられる時から、千二百九十日が定められている。"}, "12": {"en": "Blessed is he who waits, and comes to the one thousand three hundred thirty-five days.", "zh": "等到一千三百三十五日的，那人便為有福。", "ja": "待っていて千三百三十五日に至る者はさいわいです。"}, "13": {"en": "“But go your way until the end; for you will rest, and will stand in your inheritance at the end of the days.”", "zh": "「你且去等候結局，因為你必安歇。到了末期，你必起來，享受你的福分。」", "ja": "しかし、終りまであなたの道を行きなさい。あなたは休みに入り、定められた日の終りに立って、あなたの分を受けるでしょう」。"}}}}};
